        "Η ιστορία αρχίζει με ένα τηλεφώνημα Είναι Δευτέρα πρωί. Χτυπάει το τηλέφωνο. Ένας ιδιοκτήτης φωτοβολταϊκού πάρκου λέει: «Σε δύο μήνες κάνουμε repowering. Θα βγάλουμε περίπου 5.000 πάνελ. Σας ενδιαφέρουν;» Ο άπειρος πωλητής σκέφτεται: 5.000 πάνελ = πολύ καλό lead. Ο εκπαιδευμένος πωλητής σκέφτεται: Ίσως. Πρέπει πρώτα να καταλάβω τι ακριβώς είναι αυτά τα 5.000 πάνελ. Γιατί δύο stock των 5.000 πάνελ μπορούν να έχουν τελείως διαφορετική αξία. Το ένα μπορεί να είναι: καθαρό, ομοιόμορφο, λειτουργικό, εύκολο στη φόρτωση, κατάλληλων διαστάσεων, χωρίς σοβαρές φθορές. Το άλλο μπορεί να έχει:",
