        "Ο ιδιοκτήτης μας είπε: «Έχω 5.000 panels.» Στην αρχή ξέραμε μόνο έναν αριθμό. Τώρα ο εκπαιδευμένος πωλητής ξέρει να ανακαλύψει: Τι panels; Πόσα Watt; Ποιο model; Πόσων ετών; Γιατί αφαιρούνται; Τι κατάσταση έχουν; Υπάρχει yellowing; Cracked backsheets; Snail trails; Broken glass; Hot spots; Cut cables; Damaged frames; Τι διαστάσεις έχουν; Τι πάχος frame; Τι βάρος; Πόσα χωρούν σε container; Υπάρχει forklift; Πού βρίσκονται; Έχουν γίνει tests; Πότε είναι διαθέσιμα; Μόνο τότε το: «Έχω 5.000 panels» μετατρέπεται σε: εμπορική πληροφορία πάνω στην οποία μπορούμε να πάρουμε απόφαση.",
