  "me-services": [
    [
      "Αναλυτική μελέτη από το εκπαιδευτικό εγχειρίδιο",
      [
        "Μάθημα 3 – Η Ζωή ενός Φωτοβολταϊκού Πάρκου Εκπαίδευση B2B πωλητών στις υπηρεσίες της εταιρείας",
        "Πρόλογος – Δεν πουλάμε 11 άσχετες υπηρεσίες Φανταστείτε ότι κάποιος αποφασίζει σήμερα: «Θέλω να δημιουργήσω ένα φωτοβολταϊκό πάρκο.» Από εκείνη τη στιγμή ξεκινά μια ιστορία που μπορεί να διαρκέσει δεκαετίες. Το έργο πρέπει: να βρει κατάλληλο χώρο, να μελετηθεί, να αδειοδοτηθεί, να κατασκευαστεί, να ηλεκτρολογηθεί, να λειτουργήσει, να συντηρείται, να καθαρίζεται, να παρακολουθείται, να αναβαθμίζεται, ίσως κάποια στιγμή να πουληθεί. Άρα οι υπηρεσίες της MELAS ENERGEIAKI δεν είναι 11 τυχαίες υπηρεσίες. Είναι: Ο κύκλος ζωής ενός ενεργειακού asset. Ο πωλητής πρέπει να μάθει να βλέπει πού βρίσκεται ο πελάτης μέσα σε αυτόν τον κύκλο.",
        "ΥΠΗΡΕΣΙΑ 01 Χωροθέτηση και Έλεγχος Καταλληλότητας Η ιστορία Ένας επενδυτής έχει ένα χωράφι. Λέει: «Έχω 50 στρέμματα. Μπορώ να βάλω φωτοβολταϊκά;» Ο άπειρος πωλητής σκέφτεται: «Έχει χώρο, άρα γίνεται.» Όχι. Πρέπει πρώτα να εξεταστεί αν ο χώρος είναι κατάλληλος.",
        "Τι εξετάζεται γενικά μέγεθος και σχήμα οικοπέδου, προσανατολισμός, κλίση εδάφους, σκιάσεις, πρόσβαση, δυνατότητα κατασκευής, απόσταση από κατάλληλα σημεία ηλεκτρικής σύνδεσης, περιβαλλοντικοί ή χωροταξικοί περιορισμοί, ιδιοκτησιακή κατάσταση, τεχνικοί περιορισμοί. Ο πωλητής δεν κάνει τον έλεγχο. Πρέπει να καταλαβαίνει γιατί απαιτείται.",
        "Ποιος μπορεί να είναι πελάτης ιδιοκτήτης γης, επενδυτής, developer, εταιρεία ΑΠΕ, βιομηχανία, εταιρεία real estate, επενδυτικό fund.",
        "Ερωτήσεις πωλητή «Έχετε ήδη συγκεκριμένο χώρο;» «Πόση περίπου έκταση είναι;» «Είναι ιδιόκτητος ή υπό μίσθωση;» «Έχει γίνει κάποια πρώτη τεχνική αξιολόγηση;» «Έχετε εξετάσει τη δυνατότητα σύνδεσης;» «Σε ποιο στάδιο βρίσκεται σήμερα το project;»",
        "Red flags ασαφές ιδιοκτησιακό καθεστώς, πολύ δύσκολη πρόσβαση, έντονες σκιάσεις, πολύ προβληματική μορφολογία, άγνωστοι περιορισμοί χρήσης, πελάτης που θεωρεί ότι «επειδή έχω χωράφι, μπορώ αύριο να χτίσω πάρκο». Ο πωλητής δεν απορρίπτει. Λέει: «Αυτό χρειάζεται πρώτα τεχνικό και χωροταξικό έλεγχο.»",
        "ΥΠΗΡΕΣΙΑ 02 Μελέτες και Αδειοδοτήσεις Η ιστορία συνεχίζεται Το χωράφι φαίνεται κατάλληλο. Ο επενδυτής όμως δεν μπορεί απλώς να αγοράσει πάνελ και να αρχίσει να τα τοποθετεί. Χρειάζεται: τεχνικός σχεδιασμός, κατάλληλες εγκρίσεις, αδειοδοτικές διαδικασίες, διαδικασίες σύνδεσης, έγγραφα και μελέτες ανάλογα με το έργο.",
        "Τι πουλάμε πραγματικά Δεν πουλάμε: «χαρτιά». Πουλάμε: τη μετάβαση από την ιδέα σε ένα έργο που μπορεί να προχωρήσει νόμιμα και τεχνικά.",
        "Ποιος είναι ο πελάτης developer, ιδιοκτήτης έργου, επενδυτής, βιομηχανική επιχείρηση, εταιρεία ΑΠΕ.",
        "Ερωτήσεις «Σε ποιο στάδιο αδειοδότησης βρίσκεται το έργο;» «Έχει ήδη αναλάβει κάποιος τις μελέτες;» «Υπάρχει συγκεκριμένο χρονοδιάγραμμα;» «Υπάρχουν εκκρεμότητες που καθυστερούν το έργο;» «Ποιος συντονίζει σήμερα το development;»",
        "Opportunity signal Η φράση: «Έχουμε το project αλλά έχουμε κολλήσει στο...» είναι πολύ σημαντική. Όπου υπάρχει bottleneck, μπορεί να υπάρχει ανάγκη υπηρεσίας.",
        "ΥΠΗΡΕΣΙΑ 03 Διαμόρφωση και Προετοιμασία Χώρου Τώρα μπαίνουν οι μπουλντόζες Το project έχει προχωρήσει. Αλλά το χωράφι μπορεί να είναι: γεμάτο βλάστηση, ανώμαλο, δύσκολο στην πρόσβαση, χωρίς περίφραξη, χωρίς δρόμους, χωρίς υποδομές. Πριν μπουν πάνελ: ο χώρος πρέπει να γίνει εργοτάξιο.",
        "Εργασίες μπορεί να περιλαμβάνουν καθαρισμό χώρου, χωματουργικές εργασίες, διαμόρφωση εδάφους, δρόμους πρόσβασης, περίφραξη, αποστράγγιση, βάσεις υποδομών, βοηθητικούς χώρους.",
        "Πωλητής – βασική ερώτηση «Το site είναι ήδη construction-ready;» Αν όχι: υπάρχει πιθανό opportunity.",
        "Πιθανά προβλήματα δύσκολη πρόσβαση βαρέων οχημάτων, πολύ μεγάλη κλίση, προβλήματα νερών, πέτρες, βλάστηση, πολύ μαλακό ή προβληματικό έδαφος, ανάγκη σημαντικών χωματουργικών. Όλα αυτά μπορεί να επηρεάζουν: κόστος + χρόνο + τρόπο κατασκευής.",
        "ΥΠΗΡΕΣΙΑ 04 Προμήθεια και Τοποθέτηση Εξοπλισμού Το χωράφι είναι έτοιμο Τώρα φτάνουν: πάνελ, βάσεις, inverters, ηλεκτρικός εξοπλισμός, καλώδια, λοιπά συστήματα. Εδώ μπαίνουμε βαθιά στο κομμάτι: procurement + installation.",
        "Ο πωλητής δεν πουλά «ένα πάνελ» Πρέπει να σκέφτεται: ολόκληρη αλυσίδα εξοπλισμού.",
        "Πιθανός πελάτης developer, EPC, ιδιοκτήτης έργου, βιομηχανία, επενδυτής.",
        "Ερωτήσεις «Έχει κλειδώσει ο εξοπλισμός του έργου;» «Έχουν επιλεγεί modules και inverters;» «Έχει κλείσει ο προμηθευτής;» «Πότε πρέπει να παραδοθεί ο εξοπλισμός;» «Υπάρχει συγκεκριμένο BoQ;» «Ποιος έχει την ευθύνη procurement;»",
        "Μεγάλο opportunity signal «Έχουμε project αλλά δεν έχουμε κλείσει ακόμη όλο τον εξοπλισμό.»",
        "Αρνητικά που κοιτάμε πολύ στενό delivery schedule, ασαφείς τεχνικές προδιαγραφές, προβλήματα διαθεσιμότητας, δύσκολη πρόσβαση site, εξοπλισμός που δεν είναι συμβατός, πελάτης που ζητά τελική τιμή χωρίς BoQ/specification. Ο πωλητής δεν τιμολογεί μόνος του.",
        "ΥΠΗΡΕΣΙΑ 05 Ηλεκτρολογικές και Τεχνικές Εργασίες Τα πάνελ τοποθετήθηκαν Αλλά ακόμη δεν έχουμε λειτουργικό ηλεκτρικό σταθμό. Πρέπει να γίνει το ηλεκτρικό μέρος.",
        "Ενδεικτικά περιλαμβάνει DC καλωδιώσεις, AC καλωδιώσεις, συνδέσεις, πίνακες, προστασίες, γειώσεις, inverter connections, μετασχηματιστές, τεχνικές εργασίες, testing και commissioning ανάλογα με το scope.",
        "Η λέξη Commissioning Ο πωλητής πρέπει να τη γνωρίζει. Commissioning είναι η διαδικασία ελέγχων και ενεργειών πριν ένα σύστημα παραδοθεί για κανονική λειτουργία. Με απλά λόγια: «Ελέγχουμε ότι αυτό που κατασκευάσαμε λειτουργεί σωστά και με ασφάλεια.»",
        "Ποιος αγοράζει αυτή την υπηρεσία EPC, developer, park owner, general contractor, εταιρεία που χρειάζεται επιπλέον τεχνικό συνεργείο.",
        "Opportunity signals «Μας λείπουν ηλεκτρολόγοι.» «Έχουμε καθυστέρηση στο έργο.» «Χρειαζόμαστε δεύτερο συνεργείο.» «Έχουμε πρόβλημα στο commissioning.» «Χρειαζόμαστε subcontractor.» Όλα αυτά είναι δυνατά leads.",
        "ΥΠΗΡΕΣΙΑ 06 Τεχνική Συντήρηση και Επισκευές Το πάρκο αρχίζει να δουλεύει Τώρα ο επενδυτής περιμένει: παραγωγή. Κάθε ώρα που ένα μέρος του πάρκου δεν δουλεύει μπορεί να σημαίνει: χαμένη ενέργεια → χαμένα έσοδα. Εδώ αρχίζει η αξία του O&M.",
        "O&M Operations & Maintenance Λειτουργία και συντήρηση.",
        "Τι μπορεί να συμβεί inverter fault, string fault, connector failure, cable problem, fuse/protection issue, tracker fault, communication fault, sensor problem, mechanical problem, damaged module, transformer/substation problem. Ο πωλητής δεν διαγιγνώσκει. Ακούει: «Έχουμε βλάβη.» και σκέφτεται: Technical Service Opportunity.",
        "Η πιο σημαντική έννοια Downtime Χρόνος κατά τον οποίο εξοπλισμός δεν παράγει όπως πρέπει. Για έναν ιδιοκτήτη πάρκου: downtime = πιθανή απώλεια χρημάτων.",
        "Ερωτήσεις «Ποιος έχει σήμερα το O&M;» «Υπάρχει συμβόλαιο συντήρησης;» «Καλύπτει και emergency interventions;» «Τι response time έχετε;» «Έχετε συχνά προβλήματα που απαιτούν εξωτερικό συνεργείο;» «Έχετε ανάγκη δεύτερου συνεργάτη σε περιόδους αυξημένου φόρτου;»",
        "ΥΠΗΡΕΣΙΑ 07 Καθαρισμός και Συντήρηση Πάρκου Ο αθόρυβος εχθρός Το πάρκο μπορεί να λειτουργεί τεχνικά τέλεια. Αλλά πάνω στα πάνελ μαζεύονται: σκόνη, χώμα, γύρη, περιττώματα πτηνών, ρύποι. Και κάτω από τα πάνελ: χόρτα, θάμνοι, βλάστηση.",
        "Γιατί μας νοιάζει Η βρωμιά μπορεί να μειώνει το φως που φτάνει στα cells. Η βλάστηση μπορεί: να δημιουργήσει σκιά, να δυσκολεύσει την πρόσβαση, να δημιουργήσει κίνδυνο φωτιάς, να εμποδίσει εργασίες συντήρησης.",
        "Δεν πουλάμε «σφουγγάρισμα» Πουλάμε: φροντίδα του παραγωγικού asset.",
        "Ερωτήσεις «Πόσο συχνά καθαρίζετε τα modules;» «Πότε έγινε ο τελευταίος καθαρισμός;» «Ποιος αναλαμβάνει vegetation management;» «Έχετε ενιαίο συνεργάτη για όλα τα πάρκα;» «Πότε έχετε τον επόμενο προγραμματισμένο καθαρισμό;»",
        "Opportunity signal Ο πελάτης λέει: «Καθαρίζουμε όταν δούμε ότι χρειάζεται.» Αυτό σημαίνει ότι πιθανώς δεν έχει οργανωμένο πρόγραμμα.",
        "ΥΠΗΡΕΣΙΑ 08 Έλεγχος Απόδοσης και Repowering Το πάρκο γερνάει Πέρασαν χρόνια. Η τεχνολογία προχώρησε. Το πάρκο μπορεί: να αποδίδει λιγότερο, να έχει παλαιότερα modules, να έχει προβληματικούς inverters, να έχει αυξημένες βλάβες. Ο ιδιοκτήτης αρχίζει να ρωτά: «Μπορώ να κάνω το asset καλύτερο;»",
        "Performance Δεν κοιτάμε μόνο: «Λειτουργεί;» Ρωτάμε: «Λειτουργεί όσο καλά θα έπρεπε;»",
        "Τι μπορεί να εξεταστεί πραγματική παραγωγή, historical performance, inverter efficiency, module degradation, downtime, losses, faults, δυνατότητα αναβάθμισης.",
        "Repowering Αναβάθμιση παλαιότερου φωτοβολταϊκού έργου. Μπορεί να περιλαμβάνει: νέα panels, νέα inverters, αλλαγές ηλεκτρικού εξοπλισμού, βελτίωση monitoring, αλλαγές άλλων συστημάτων.",
