        "Η υπηρεσία μπορεί να περιλαμβάνει αποξήλωση, διαχείριση παλιού εξοπλισμού, εγκατάσταση νέου, ηλεκτρικές προσαρμογές, testing, recommissioning.",
        "Ο πωλητής πρέπει ΠΑΝΤΑ να ρωτά «Τι θα γίνει με τον εξοπλισμό που αφαιρείται;» Γιατί εκεί μπορεί να βρίσκεται δεύτερο deal.",
        "Μεγάλη προσοχή Κατά την αποξήλωση: δεν κόβουμε αδικαιολόγητα cables, δεν πετάμε modules, δεν λυγίζουμε frames, δεν στοιβάζουμε πρόχειρα, δεν προκαλούμε microcracks. Ένα πάνελ που είχε αξία πάνω στο πάρκο μπορεί να χάσει αξία μέσα σε λίγα λεπτά κακού handling.",
        "ΥΠΗΡΕΣΙΑ 10 Αγοραπωλησίες Φωτοβολταϊκών Πάρκων Το ίδιο το πάρκο γίνεται προϊόν Ένα φωτοβολταϊκό πάρκο δεν είναι μόνο ηλεκτρολογική εγκατάσταση. Είναι: επενδυτικό asset. Μπορεί να αγοράζεται και να πωλείται.",
        "Ένας αγοραστής κοιτάει γενικά εγκατεστημένη ισχύ, πραγματική παραγωγή, ηλικία, εξοπλισμό, κατάσταση, ιστορικό λειτουργίας, συμβάσεις, δικαιώματα, γη/μίσθωση, οικονομικά στοιχεία, τεχνικούς κινδύνους.",
        "Due Diligence Πολύ σημαντικός όρος. Due diligence = αναλυτικός έλεγχος πριν από μία μεγάλη συναλλαγή. Μπορεί να έχει: τεχνικό μέρος, οικονομικό μέρος, νομικό μέρος, φορολογικό μέρος. Ο πωλητής δεν κάνει due diligence. Πρέπει όμως να ξέρει τι σημαίνει.",
        "Ερωτήσεις «Το πάρκο βρίσκεται σε λειτουργία;» «Ποια είναι η ισχύς του;» «Πότε μπήκε σε λειτουργία;» «Υπάρχει πραγματική πρόθεση πώλησης;» «Υπάρχει συγκεκριμένο asking price;» «Ποιος είναι ο ιδιοκτήτης;» «Υπάρχει ήδη advisor ή broker;» «Έχετε διαθέσιμο data room;»",
        "Data Room Χώρος — συνήθως ψηφιακός — όπου συγκεντρώνονται τα έγγραφα μιας επενδυτικής συναλλαγής. Αν ακουστεί: «Data room is ready.» σημαίνει ότι η διαδικασία πιθανόν είναι αρκετά προχωρημένη.",
        "ΥΠΗΡΕΣΙΑ 11 Οικιακά Φωτοβολταϊκά Συστήματα Και η ιστορία μικραίνει Από ένα τεράστιο πάρκο πολλών MW πηγαίνουμε σε ένα σπίτι. Η βασική τεχνολογία παραμένει παρόμοια. Ο πελάτης όμως είναι διαφορετικός. Δεν είναι asset manager. Μπορεί να είναι: ο ιδιοκτήτης του σπιτιού.",
        "Τι θέλει συνήθως χαμηλότερο ενεργειακό κόστος, μεγαλύτερη ενεργειακή αυτονομία, πιθανή αποθήκευση ενέργειας, αξιοποίηση στέγης.",
        "Τι πρέπει να μάθουμε τοποθεσία, διαθέσιμη επιφάνεια, είδος στέγης, σκιάσεις, κατανάλωση, ηλεκτρική εγκατάσταση, πιθανό ενδιαφέρον για battery. Ο πωλητής δεν διαστασιολογεί το σύστημα. Παίρνει τα στοιχεία.",
        "Ο ΧΑΡΤΗΣ ΤΩΝ 11 ΥΠΗΡΕΣΙΩΝ DEVELOPMENT 01 Χωροθέτηση ↓ 02 Μελέτες & Αδειοδοτήσεις ↓ CONSTRUCTION 03 Προετοιμασία χώρου ↓ 04 Προμήθεια & Τοποθέτηση Εξοπλισμού ↓ 05 Ηλεκτρολογικές & Τεχνικές Εργασίες ↓ OPERATIONS 06 Τεχνική Συντήρηση & Επισκευές ↓ 07 Καθαρισμός & Συντήρηση Πάρκου ↓ OPTIMIZATION 08 Performance & Repowering ↓ 09 Αντικατάσταση Εξοπλισμού ↓ INVESTMENT 10 Αγοραπωλησία Πάρκου και παράλληλα: RESIDENTIAL 11 Οικιακά Φωτοβολταϊκά",
        "Η ΠΙΟ ΣΗΜΑΝΤΙΚΗ ΔΕΞΙΟΤΗΤΑ ΤΟΥ ΠΩΛΗΤΗ Ο πελάτης σπάνια θα πει: «Θέλω την υπηρεσία Νο 6.» Θα πει: «Έχουμε συχνά βλάβες.» Ο πωλητής μεταφράζει: → Service 06. Ο πελάτης λέει: «Έχουμε παλιό πάρκο και θέλουμε να δούμε αν αξίζει να το αναβαθμίσουμε.» → Service 08. Ο πελάτης λέει: «Του χρόνου αλλάζουμε 8.000 panels.» → Service 08 + 09 + panel sourcing. Ο πελάτης λέει: «Έχουμε νέο project αλλά δεν έχουμε κλείσει τα ηλεκτρολογικά.» → Service 05. Ο πελάτης λέει: «Σκεφτόμαστε να πουλήσουμε το πάρκο.» → Service 10. Αυτό είναι Sales Intelligence.",
        "Οι 8 λέξεις που πρέπει να ενεργοποιούν τον πωλητή Όταν ακούει: «ΝΕΟ ΕΡΓΟ» → 01–05 «ΚΑΘΥΣΤΕΡΗΣΗ» → πιθανό subcontracting opportunity «ΒΛΑΒΗ» → 06 «ΣΥΝΤΗΡΗΣΗ» → 06–07 «ΧΑΜΗΛΗ ΑΠΟΔΟΣΗ» → 06–08 «REPOWERING» → 08–09 + panels «ΑΝΤΙΚΑΤΑΣΤΑΣΗ» → 09 + panels «ΠΩΛΗΣΗ ΠΑΡΚΟΥ» → 10",
        "Το μεγαλύτερο λάθος Να ακούσει ο πωλητής: «Θα αλλάξουμε πάνελ.» και να δει μόνο μία ευκαιρία. Μπορεί στην πραγματικότητα να υπάρχουν: performance assessment, engineering, procurement, dismantling, installation, electrical works, testing, αγορά παλιών panels. Ένα γεγονός μπορεί να δημιουργήσει: Πολλαπλές υπηρεσίες.",
