      "3. Ποιος αποφασίζει;",
      [
        "Owner, technical manager, procurement, asset manager;"
      ]
    ],
    [
      "4. Πόσο μεγάλο είναι;",
      [
        "MW, αριθμός parks, scope εργασιών;"
      ]
    ],
    [
      "5. Τι γίνεται μετά;",
      [
        "Meeting, RFQ, site visit, proposal;",
        "Το μνημονικό ΕΡΓΟ Όταν ο πωλητής χαθεί, θυμάται: Ε – Εξέλιξη Τι πρόκειται να συμβεί; Ρ – Ρόλος Ποιος είναι ο άνθρωπος που μιλάμε; Γ – Γεωγραφία & μέγεθος Πού είναι το έργο και πόσο μεγάλο είναι; Ο – Ορίζοντας Πότε θα γίνει; ΕΡΓΟ Αν έχει αυτά τα τέσσερα, έχει αρχίσει να καταλαβαίνει την ευκαιρία.",
        "Τελική φιλοσοφία Ο πωλητής της MELAS ENERGEIAKI δεν χρειάζεται να πείθει κάθε εταιρεία να αγοράσει κάτι. Πρέπει να μάθει να αναγνωρίζει: πού βρίσκεται το έργο, τι πρόκειται να συμβεί στη συνέχεια, ποιο πρόβλημα υπάρχει, ποια υπηρεσία μπορεί να λύσει αυτό το πρόβλημα, και ποιος είναι ο κατάλληλος άνθρωπος για να συνεχίσουμε τη συζήτηση. Όταν μάθει να βλέπει τον κύκλο ζωής του έργου, οι 11 υπηρεσίες παύουν να είναι 11 ξεχωριστά προϊόντα.⁰ Γίνονται: μία ενιαία ιστορία."
      ]
