  ],
  "me-construction": [
    [
      "Αναλυτική μελέτη από το εκπαιδευτικό εγχειρίδιο",
      [
        "Μάθημα 4 – Από το χωράφι μέχρι να αρχίσει να λειτουργεί το φωτοβολταϊκό πάρκο Σε αυτό το μάθημα θα δούμε τις πρώτες 5 υπηρεσίες της εταιρείας. Θα ακολουθήσουμε την ιστορία ενός ανθρώπου που λέει: «Θέλω να φτιάξω ένα φωτοβολταϊκό πάρκο.» Από αυτή τη στιγμή μέχρι να αρχίσει το πάρκο να παράγει ρεύμα, πρέπει να γίνουν πολλά πράγματα. Η σειρά είναι περίπου: Βρίσκω χώρο → Ελέγχω αν κάνει → Κάνω μελέτες και άδειες → Ετοιμάζω τον χώρο → Αγοράζω και τοποθετώ εξοπλισμό → Κάνω τις ηλεκτρολογικές εργασίες Αυτές είναι οι πρώτες 5 υπηρεσίες μας.",
        "ΥΠΗΡΕΣΙΑ 01 Χωροθέτηση και Έλεγχος Καταλληλότητας Τι είναι με πολύ απλά λόγια; Κάποιος έχει ένα χωράφι ή σκέφτεται να νοικιάσει έναν χώρο. Πριν ξοδέψει χρήματα πρέπει να απαντήσει στην ερώτηση: «Μπορεί πραγματικά να γίνει εδώ φωτοβολταϊκό πάρκο;» Αυτό εξετάζει η συγκεκριμένη υπηρεσία.",
        "Ένα απλό παράδειγμα Ο κύριος Νίκος έχει ένα μεγάλο χωράφι. Μας λέει: «Είναι μεγάλο και έχει πολύ ήλιο. Άρα μπορώ να βάλω φωτοβολταϊκά.» Όχι απαραίτητα. Μπορεί: να έχει μεγάλη κλίση, να σκιάζεται, να μην υπάρχει εύκολη πρόσβαση, να υπάρχουν περιορισμοί, να υπάρχει πρόβλημα με τη σύνδεση στο ηλεκτρικό δίκτυο, να μην είναι ξεκάθαρο σε ποιον ανήκει, να χρειάζονται πολύ ακριβές εργασίες για να γίνει κατάλληλο. Άρα πρώτα: ελέγχουμε τον χώρο.",
        "Τι κοιτάζει η τεχνική ομάδα; Ο πωλητής δεν χρειάζεται να κάνει αυτούς τους ελέγχους. Πρέπει όμως να ξέρει τι περίπου εξετάζεται. Μέγεθος Υπάρχει αρκετός χώρος; Σχήμα Ένα πολύ περίεργο ή στενό οικόπεδο μπορεί να δυσκολεύει την εγκατάσταση. Κλίση Είναι επίπεδο ή πολύ απότομο; Ήλιος και σκιά Υπάρχουν: βουνά, δέντρα, κτίρια, που δημιουργούν μεγάλη σκιά; Πρόσβαση Μπορούν να φτάσουν: φορτηγά, μηχανήματα, συνεργεία; Έδαφος Μπορούν να γίνουν οι απαραίτητες κατασκευές; Ηλεκτρικό δίκτυο Υπάρχει δυνατότητα να συνδεθεί το έργο; Νομικοί και χωροταξικοί περιορισμοί Επιτρέπεται να γίνει το έργο στη συγκεκριμένη περιοχή;",
        "Τι πρέπει να καταλάβει ο πωλητής; Ο πελάτης δεν αγοράζει απλώς έναν «έλεγχο χωραφιού». Θέλει να αποφύγει το εξής: να επενδύσει χρόνο και χρήματα σε έναν χώρο που τελικά δεν μπορεί να χρησιμοποιηθεί σωστά.",
        "Ποιον ψάχνουμε; Πιθανοί πελάτες: ιδιοκτήτες γης, επενδυτές, εταιρείες ενέργειας, εταιρείες που αναπτύσσουν νέα φωτοβολταϊκά έργα, βιομηχανίες, επιχειρήσεις με μεγάλες εκτάσεις.",
        "Τι ρωτά ο πωλητής; Απλές ερωτήσεις: «Έχετε ήδη βρει τον χώρο;» «Πού βρίσκεται;» «Πόσο μεγάλη είναι περίπου η έκταση;» «Είναι δικός σας ή πρόκειται να τον νοικιάσετε;» «Έχει γίνει κάποιος έλεγχος μέχρι σήμερα;» «Σε ποιο στάδιο βρίσκεται το σχέδιό σας;»",
        "Τι μας δείχνει καλή ευκαιρία; Ο πελάτης λέει: «Έχω τον χώρο αλλά δεν έχω κάνει κανέναν έλεγχο ακόμα.» ή: «Εξετάζουμε δύο-τρεις διαφορετικές τοποθεσίες.» ή: «Θέλουμε να ξεκινήσουμε νέο φωτοβολταϊκό έργο.» Αυτές είναι καλές αφορμές για συζήτηση.",
        "Τι πρέπει να προσέχει ο πωλητής; Δεν λέμε ποτέ: «Ναι, το χωράφι σας κάνει.» Ο πωλητής δεν μπορεί να το ξέρει. Λέμε: «Αυτό πρέπει να εξεταστεί από την τεχνική μας ομάδα.»",
        "ΥΠΗΡΕΣΙΑ 02 Μελέτες και Αδειοδοτήσεις Το πρώτο βήμα τελείωσε. Βρήκαμε έναν χώρο που φαίνεται κατάλληλος. Τώρα ο πελάτης λέει: «Ωραία. Πάμε να βάλουμε πάνελ.» Όχι ακόμα. Πριν κατασκευαστεί το έργο πρέπει να σχεδιαστεί σωστά και να ακολουθηθούν οι απαραίτητες διαδικασίες.",
        "Τι είναι η μελέτη; Με πολύ απλά λόγια: Η μελέτη είναι το σχέδιο του έργου. Όπως δεν χτίζεις ένα σπίτι χωρίς σχέδιο, έτσι δεν πρέπει να φτιάξεις ένα φωτοβολταϊκό πάρκο χωρίς τεχνικό σχεδιασμό. Πρέπει να αποφασιστεί: πού θα μπουν τα πάνελ, πόσα θα μπουν, πώς θα συνδεθούν, πού θα μπουν οι inverter, πού θα περάσουν τα καλώδια, ποιος ηλεκτρικός εξοπλισμός χρειάζεται, πώς θα γίνει η σύνδεση. Ο πωλητής δεν κάνει κανέναν από αυτούς τους υπολογισμούς. Πρέπει μόνο να καταλαβαίνει τι σημαίνει μελέτη.",
        "Τι είναι η αδειοδότηση; Με απλά λόγια: Είναι οι διαδικασίες και οι εγκρίσεις που χρειάζονται για να προχωρήσει νόμιμα το έργο. Ανάλογα με το έργο μπορεί να χρειάζονται διαφορετικές διαδικασίες και έγγραφα. Ο πωλητής δεν χρειάζεται να γνωρίζει κάθε νόμο και κάθε έντυπο. Πρέπει να ρωτήσει: «Σε ποιο στάδιο βρίσκεται σήμερα το έργο;»",
        "Η σημαντικότερη εικόνα Ο πελάτης μπορεί να βρίσκεται: Στάδιο Α «Έχω μόνο την ιδέα.» Στάδιο Β «Έχω βρει χώρο.» Στάδιο Γ «Έχουν ξεκινήσει οι μελέτες.» Στάδιο Δ «Περιμένω εγκρίσεις.» Στάδιο Ε «Έχω σχεδόν τελειώσει και ετοιμάζομαι να κατασκευάσω.» Ο πωλητής πρέπει να μάθει: Σε ποιο στάδιο βρίσκεται;",
        "Τι ρωτάμε; «Έχουν ξεκινήσει οι μελέτες;» «Έχετε ήδη μηχανικό ή εταιρεία που το έχει αναλάβει;» «Υπάρχει κάποια εκκρεμότητα;» «Έχει καθυστερήσει κάτι;» «Πότε θέλετε να ξεκινήσει η κατασκευή;»",
        "Πολύ καλό σημάδι Ο πελάτης λέει: «Έχουμε κολλήσει.» Ο πωλητής πρέπει αμέσως να ρωτήσει: «Σε ποιο σημείο;» Δεν χρειάζεται να λύσει το πρόβλημα. Πρέπει να το καταλάβει και να φέρει την κατάλληλη ομάδα.",
        "Παράδειγμα Πελάτης: «Έχουμε το project εδώ και μήνες αλλά υπάρχουν ακόμα εκκρεμότητες στις μελέτες.» Κακή απάντηση: «Α, εντάξει.» Καλή απάντηση: «Ποια ακριβώς μελέτη ή διαδικασία εκκρεμεί; Αν μου δώσετε λίγες πληροφορίες, μπορούμε να δούμε αν μπορεί να σας βοηθήσει η ομάδα μας.»",
        "ΥΠΗΡΕΣΙΑ 03 Διαμόρφωση και Προετοιμασία Χώρου Τώρα το έργο έχει προχωρήσει. Έχουμε χώρο. Έχουμε σχέδιο. Έχουμε τις απαραίτητες διαδικασίες σε εξέλιξη ή ολοκληρωμένες. Τώρα πρέπει το χωράφι: να γίνει κατάλληλο για κατασκευή.",
        "Φανταστείτε ένα χωράφι Μπορεί να έχει: ψηλά χόρτα, πέτρες, ανώμαλο έδαφος, νερά όταν βρέχει, καθόλου δρόμο, καθόλου περίφραξη. Δεν μπορεί απλώς να έρθει ένα φορτηγό με 5.000 πάνελ και να αρχίσουμε να τα βάζουμε. Πρέπει πρώτα να ετοιμαστεί ο χώρος.",
        "Τι εργασίες μπορεί να χρειαστούν; Καθαρισμός χώρου Απομακρύνονται: χόρτα, θάμνοι, εμπόδια. Χωματουργικές εργασίες Μηχανήματα μπορεί να χρειαστεί να διορθώσουν το έδαφος. Δρόμοι πρόσβασης Πρέπει να μπορούν να μπουν: φορτηγά, γερανοί, συνεργεία, μηχανήματα. Περίφραξη Το φωτοβολταϊκό πάρκο πρέπει να προστατεύεται. Αποστράγγιση Πρέπει να αποφεύγονται προβλήματα από νερά και πλημμύρες. Βοηθητικοί χώροι Μπορεί να χρειάζονται χώροι για: εξοπλισμό, τεχνικές εγκαταστάσεις, αποθήκευση.",
        "Τι πουλάμε πραγματικά; Δεν πουλάμε απλώς: «χωματουργικά». Βοηθάμε να μετατραπεί: ένα απλό χωράφι σε χώρο έτοιμο να δεχτεί ένα φωτοβολταϊκό έργο.",
        "Τι ρωτά ο πωλητής; «Έχει ξεκινήσει η προετοιμασία του χώρου;» «Υπάρχει ήδη πρόσβαση για μεγάλα οχήματα;» «Χρειάζονται χωματουργικές εργασίες;» «Έχει γίνει περίφραξη;» «Πότε θέλετε να ξεκινήσει η εγκατάσταση;»",
        "Καλή εμπορική ευκαιρία Ο πελάτης λέει: «Η κατασκευή πρέπει να ξεκινήσει σε δύο μήνες και ο χώρος δεν έχει ετοιμαστεί ακόμα.» Τότε υπάρχει: πραγματική ανάγκη, συγκεκριμένο έργο, συγκεκριμένος χρόνος. Αυτό είναι πολύ πιο δυνατό lead από κάποιον που λέει: «Ίσως κάποτε φτιάξω φωτοβολταϊκό.»",
        "ΥΠΗΡΕΣΙΑ 04 Προμήθεια και Τοποθέτηση Εξοπλισμού Ο χώρος είναι έτοιμος. Τώρα πρέπει να έρθουν τα πράγματα που θα δημιουργήσουν το φωτοβολταϊκό πάρκο.",
        "Τι εξοπλισμός χρειάζεται; Ο πωλητής πρέπει να γνωρίζει τουλάχιστον τις βασικές κατηγορίες. Φωτοβολταϊκά πάνελ Παράγουν ηλεκτρική ενέργεια από τον ήλιο. Βάσεις Πάνω τους τοποθετούνται τα πάνελ. Inverter Παίρνουν το ρεύμα που παράγουν τα πάνελ και το μετατρέπουν στη μορφή που χρειάζεται το σύστημα. Καλώδια Μεταφέρουν το ηλεκτρικό ρεύμα. Ηλεκτρικοί πίνακες και προστασίες Χρησιμοποιούνται για τη σωστή και ασφαλή λειτουργία της εγκατάστασης. Μετασχηματιστής Σε μεγαλύτερα έργα βοηθά ώστε η ηλεκτρική ενέργεια να φτάσει στην κατάλληλη τάση για το δίκτυο.",
        "Τι σημαίνει «προμήθεια»; Πολύ απλά: Αγοράζουμε και οργανώνουμε τον εξοπλισμό που χρειάζεται το έργο. Ο πωλητής μπορεί να ακούσει τη λέξη: Procurement Procurement = η διαδικασία αγοράς και εξασφάλισης του εξοπλισμού και των υλικών.",
        "Και μετά έρχεται η τοποθέτηση Δεν αρκεί να αγοράσουμε 5.000 πάνελ. Πρέπει: να φτάσουν στο έργο, να αποθηκευτούν σωστά, να τοποθετηθούν στις βάσεις, να συνδεθούν σωστά.",
        "Ποιον πελάτη ψάχνουμε; Μία εταιρεία που: κατασκευάζει νέο έργο, έχει αναλάβει μεγάλο φωτοβολταϊκό πάρκο, δεν έχει αγοράσει ακόμα όλο τον εξοπλισμό, ψάχνει προμηθευτές, ψάχνει συνεργείο εγκατάστασης.",
        "Τι ρωτά ο πωλητής; «Έχετε ήδη επιλέξει τα πάνελ;» «Έχετε ήδη επιλέξει τους inverter;» «Έχει αγοραστεί όλος ο εξοπλισμός;» «Πότε πρέπει να βρίσκεται στο έργο;» «Χρειάζεστε μόνο εξοπλισμό ή και εγκατάσταση;» «Πόσο μεγάλο είναι το έργο;»",
        "Μία λέξη που πρέπει να γνωρίζει: BoQ Ο πελάτης μπορεί να πει: «Θα σας στείλω το BoQ.» Τι σημαίνει; BoQ = Bill of Quantities Με πολύ απλά λόγια: Η λίστα με όσα χρειάζεται το έργο και σε ποιες ποσότητες. Για παράδειγμα: 5.000 πάνελ, 20 inverter, τόσα μέτρα καλώδιο, τόσες βάσεις. Ο πωλητής δεν χρειάζεται να φτιάξει το BoQ. Πρέπει να ξέρει ότι: αν υπάρχει BoQ, έχουμε πολύ πιο συγκεκριμένο έργο.",
        "Πολύ δυνατό σημάδι Ο πελάτης λέει: «Το έργο είναι έτοιμο αλλά δεν έχουμε κλείσει ακόμα τον εξοπλισμό.» Αυτό είναι σοβαρή εμπορική ευκαιρία.",
        "Τι δεν κάνει ο πωλητής; Δεν λέει: «Μπορούμε να σας δώσουμε 10.000 πάνελ σε αυτή την τιμή.» αν δεν έχει πάρει έγκριση. Λέει: «Στείλτε μας τα στοιχεία του έργου και τις τεχνικές απαιτήσεις και θα το εξετάσει η αρμόδια ομάδα.»",
        "ΥΠΗΡΕΣΙΑ 05 Ηλεκτρολογικές και Τεχνικές Εργασίες Τώρα έχουμε: τον χώρο, τις βάσεις, τα πάνελ, τους inverter. Αλλά υπάρχει ένα πρόβλημα. Αν απλώς τα αφήσουμε εκεί: δεν έχουμε λειτουργικό φωτοβολταϊκό πάρκο. Πρέπει όλα να συνδεθούν σωστά.",
        "Τι κάνουν οι ηλεκτρολόγοι; Με πολύ απλά λόγια: Ενώνουν σωστά όλα τα κομμάτια του συστήματος ώστε το ρεύμα να μπορεί να φτάσει με ασφάλεια από τα πάνελ μέχρι το δίκτυο.",
        "Τι εργασίες μπορεί να υπάρχουν; Συνδέσεις πάνελ Τα πάνελ συνδέονται μεταξύ τους. Καλωδιώσεις Περνούν τα καλώδια που μεταφέρουν το ρεύμα. Inverter Συνδέονται στο σύστημα. Πίνακες Γίνονται οι κατάλληλες ηλεκτρικές συνδέσεις. Γειώσεις Πολύ σημαντικές για την ασφάλεια. Μετασχηματιστής και υπόλοιπος εξοπλισμός Συνδέονται ανάλογα με το έργο. Έλεγχοι Πριν το έργο λειτουργήσει κανονικά πρέπει να γίνουν οι απαραίτητοι τεχνικοί έλεγχοι.",
        "Τι είναι DC και AC; Απλά: Τα φωτοβολταϊκά πάνελ παράγουν: DC – συνεχές ρεύμα. Ο inverter το μετατρέπει σε: AC – εναλλασσόμενο ρεύμα. Δεν χρειάζεται ο πωλητής να ξέρει περισσότερη ηλεκτρολογία. Πρέπει να θυμάται: Πάνελ → DC → Inverter → AC",
        "Τι είναι Commissioning; Θα ακούγεται συχνά. Commissioning σημαίνει: Οι τελικοί έλεγχοι πριν το έργο ξεκινήσει κανονικά να λειτουργεί. Με απλά λόγια: «Ελέγχουμε ότι όλα έχουν γίνει σωστά και ότι το σύστημα μπορεί να λειτουργήσει.»",
        "Τι είναι Subcontractor; Πολύ σημαντική λέξη για B2B πωλητή. Subcontractor σημαίνει: Εξωτερική εταιρεία ή συνεργείο που αναλαμβάνει ένα μέρος της δουλειάς. Παράδειγμα: Μία μεγάλη εταιρεία έχει αναλάβει την κατασκευή ενός πάρκου. Έχει όμως πάρα πολλή δουλειά και δεν έχει αρκετούς ηλεκτρολόγους. Μπορεί να πει: «Χρειαζόμαστε εξωτερικό συνεργείο για τα ηλεκτρολογικά.» Αυτό είναι ευκαιρία για εμάς.",
        "Πολύ σημαντικά σημάδια για τον πωλητή Αν ακούσει: «Δεν έχουμε αρκετό προσωπικό.» ή: «Το έργο έχει καθυστέρηση.» ή: «Ψάχνουμε δεύτερο συνεργείο.» ή: «Χρειαζόμαστε ηλεκτρολόγους.» ή: «Έχουμε πολλά έργα ταυτόχρονα.» τότε πρέπει να σκεφτεί: Υπηρεσία 05.",
        "Τι ρωτάμε; «Τι εργασίες χρειάζεστε;» «Πού βρίσκεται το έργο;» «Πόσο μεγάλο είναι;» «Πότε πρέπει να ξεκινήσουν οι εργασίες;» «Έχει ξεκινήσει ήδη η κατασκευή;» «Χρειάζεστε ολόκληρο συνεργείο ή συγκεκριμένη εργασία;» «Ποιος είναι ο υπεύθυνος του έργου;»",
        "ΤΩΡΑ ΑΣ ΤΑ ΕΝΩΣΟΥΜΕ ΟΛΑ Ένας επενδυτής λέει: «Θέλω φωτοβολταϊκό πάρκο.» Βήμα 1 Βρίσκουμε και ελέγχουμε τον χώρο. Υπηρεσία 01 ↓ Βήμα 2 Σχεδιάζουμε και προχωράμε τις απαραίτητες διαδικασίες. Υπηρεσία 02 ↓ Βήμα 3 Ετοιμάζουμε το χωράφι. Υπηρεσία 03 ↓ Βήμα 4 Αγοράζουμε και τοποθετούμε εξοπλισμό. Υπηρεσία 04 ↓ Βήμα 5 Κάνουμε τις ηλεκτρολογικές και τεχνικές εργασίες. Υπηρεσία 05 ↓ Το πάρκο μπορεί να ξεκινήσει τη λειτουργία του.",
        "Πώς σκέφτεται ο καλός πωλητής; Δεν προσπαθεί να θυμηθεί 100 τεχνικές λέξεις. Προσπαθεί να απαντήσει:"
      ]
    ],
    [
      "6. Πότε πρέπει να γίνει;",
      [
        "Αυτές οι ερωτήσεις μπορούν να αποκαλύψουν σχεδόν κάθε εμπορική ευκαιρία στις υπηρεσίες 01–05.",
        "Μικρή άσκηση Ο πελάτης λέει: «Έχω 100 στρέμματα αλλά δεν έχω κάνει τίποτα ακόμα.» Πιθανή υπηρεσία: 01 – Χωροθέτηση και Έλεγχος Καταλληλότητας",
        "Ο πελάτης λέει: «Ο χώρος έχει εγκριθεί αλλά έχουμε εκκρεμότητες με τις μελέτες.» Πιθανή υπηρεσία: 02 – Μελέτες και Αδειοδοτήσεις",
        "Ο πελάτης λέει: «Θέλουμε να αρχίσουμε εγκατάσταση αλλά το χωράφι δεν είναι έτοιμο.» Πιθανή υπηρεσία: 03 – Διαμόρφωση και Προετοιμασία Χώρου",
        "Ο πελάτης λέει: «Το έργο ξεκινά αλλά δεν έχουμε αγοράσει ακόμη τα πάνελ και τους inverter.» Πιθανή υπηρεσία: 04 – Προμήθεια και Τοποθέτηση Εξοπλισμού",
        "Ο πελάτης λέει: «Έχουμε τα υλικά αλλά χρειαζόμαστε επιπλέον ηλεκτρολόγους για να τελειώσουμε εγκαίρως.» Πιθανή υπηρεσία: 05 – Ηλεκτρολογικές και Τεχνικές Εργασίες",
        "Τι πρέπει να θυμάται ο πωλητής 01 Κάνει ο χώρος; 02 Μπορεί το έργο να προχωρήσει σωστά και νόμιμα; 03 Είναι ο χώρος έτοιμος για κατασκευή; 04 Έχουμε τον εξοπλισμό και ποιος θα τον τοποθετήσει; 05 Έχουν γίνει οι ηλεκτρολογικές συνδέσεις και οι τεχνικές εργασίες; Αν θυμάται αυτές τις πέντε ερωτήσεις, έχει καταλάβει τη βασική λογική των πρώτων πέντε υπηρεσιών."
      ]
    ]
  ],
  "me-operations": [
    [
      "Αναλυτική μελέτη από το εκπαιδευτικό εγχειρίδιο",
      [
        "Μάθημα 5 – Υπηρεσίες 06–09 Τι γίνεται αφού το φωτοβολταϊκό πάρκο αρχίσει να λειτουργεί Μέχρι τώρα είδαμε πώς: βρίσκουμε τον χώρο, κάνουμε τις μελέτες, προετοιμάζουμε το έδαφος, τοποθετούμε εξοπλισμό, κάνουμε τις ηλεκτρολογικές εργασίες. Τώρα το πάρκο είναι έτοιμο. Παράγει ρεύμα. Ο ιδιοκτήτης χαίρεται. Αλλά η ιστορία δεν τελειώνει εδώ. Στην πραγματικότητα, τώρα αρχίζει ένα πολύ σημαντικό κομμάτι: Η καθημερινή ζωή του φωτοβολταϊκού πάρκου. Ένα φωτοβολταϊκό πάρκο μπορεί να λειτουργεί για πολλά χρόνια. Μέσα σε αυτά τα χρόνια: θα χρειάζεται συντήρηση, μπορεί να εμφανίσει βλάβες,",
        "θα χρειάζεται καθαρισμό, μπορεί να έχει χαμηλότερη απόδοση, ίσως κάποια στιγμή χρειαστεί αναβάθμιση. Και εδώ βρίσκονται οι υπηρεσίες: 06 – Τεχνική Συντήρηση και Επισκευές 07 – Καθαρισμός και Συντήρηση Πάρκου 08 – Έλεγχος Απόδοσης και Repowering 09 – Αντικατάσταση Πάνελ και Εξοπλισμού",
        "Το πιο σημαντικό εμπορικό μάθημα Οι υπηρεσίες 01–05 συνδέονται κυρίως με τη δημιουργία ενός έργου. Οι υπηρεσίες 06–09 μπορούν να εμφανίζονται: ξανά και ξανά. Παράδειγμα: Ένα πάρκο μπορεί: να καθαρίζεται πολλές φορές, να χρειάζεται συντήρηση κάθε χρόνο, να εμφανίζει βλάβες, να χρειάζεται περιοδικούς ελέγχους, να αντικαθιστά σταδιακά εξοπλισμό. Άρα ο πωλητής δεν πρέπει να σκέφτεται μόνο: «Πώς θα κλείσω αυτή τη δουλειά;» Πρέπει να σκέφτεται: «Πώς θα κάνω αυτόν τον πελάτη μακροχρόνιο συνεργάτη;» Αυτό είναι πολύ σημαντικό.",
        "ΥΠΗΡΕΣΙΑ 06 Τεχνική Συντήρηση και Επισκευές Η ιστορία Ένα φωτοβολταϊκό πάρκο λειτουργεί κανονικά. Μια μέρα εμφανίζεται πρόβλημα. Ένας inverter σταματά. Ένα string δεν παράγει σωστά. Ένα καλώδιο έχει πρόβλημα. Ένας connector έχει καεί. Κάποιος εξοπλισμός δεν επικοινωνεί σωστά. Ο ιδιοκτήτης έχει ένα βασικό πρόβλημα: Χάνει παραγωγή. Και όταν ένα φωτοβολταϊκό πάρκο χάνει παραγωγή: μπορεί να χάνει χρήματα.",
        "Τι σημαίνει συντήρηση; Με πολύ απλά λόγια: Φροντίζουμε το πάρκο ώστε να συνεχίζει να λειτουργεί σωστά. Υπάρχουν δύο βασικές μορφές."
      ]
    ],
    [
      "1. Προληπτική συντήρηση",
      [
        "Προληπτική σημαίνει: Δεν περιμένω να χαλάσει κάτι. Το ελέγχω πριν χαλάσει. Παράδειγμα: Όπως κάνουμε service σε ένα αυτοκίνητο. Δεν περιμένουμε να σταματήσει ο κινητήρας. Κάνουμε: ελέγχους, επιθεώρηση, μετρήσεις, καθαρισμό όπου χρειάζεται, σφίξιμο συνδέσεων, έλεγχο εξοπλισμού. Στόχος: να βρούμε το πρόβλημα πριν γίνει μεγάλη βλάβη."
      ]
    ],
    [
      "2. Διορθωτική συντήρηση",
      [
        "Εδώ το πρόβλημα έχει ήδη εμφανιστεί. Παράδειγμα: «Ένας inverter δεν λειτουργεί.» ή: «Ένα κομμάτι του πάρκου δεν παράγει.» Τώρα πρέπει: να βρούμε την αιτία, να επισκευάσουμε, να αντικαταστήσουμε κάτι αν χρειάζεται, να επαναφέρουμε το σύστημα σε λειτουργία.",
        "Τι είναι O&M; Ο πελάτης μπορεί να πει: «Έχουμε εταιρεία O&M.» O&M σημαίνει: Operations & Maintenance Με απλά λόγια: Λειτουργία και συντήρηση του πάρκου. Μία εταιρεία O&M μπορεί να είναι υπεύθυνη για: παρακολούθηση, ελέγχους, συντήρηση, επισκευές, οργάνωση τεχνικών εργασιών.",
        "Τι είναι Downtime; Πολύ σημαντική λέξη. Downtime είναι: ο χρόνος που κάποιο μέρος του πάρκου δεν λειτουργεί σωστά. Παράδειγμα: Ένας inverter σταματά για 3 ημέρες. Αυτές οι 3 ημέρες είναι downtime για αυτό το μέρος της εγκατάστασης. Όσο περισσότερο downtime υπάρχει: τόσο μεγαλύτερη μπορεί να είναι η χαμένη παραγωγή.",
        "Τι προβλήματα μπορεί να εμφανιστούν; Ο πωλητής δεν χρειάζεται να ξέρει πώς διορθώνονται. Πρέπει απλώς να αναγνωρίζει τις λέξεις. Inverter fault Πρόβλημα στον inverter. String fault Πρόβλημα σε μία ομάδα πάνελ που είναι συνδεδεμένα μεταξύ τους. Cable problem Πρόβλημα σε καλώδιο. Connector problem Πρόβλημα σε σύνδεση. Fuse problem Πρόβλημα σε ασφάλεια. Tracker problem Πρόβλημα στο σύστημα που κινεί τα πάνελ σε πάρκο με trackers. Communication problem Ο εξοπλισμός μπορεί να λειτουργεί αλλά να μην επικοινωνεί σωστά με το σύστημα παρακολούθησης. Damaged panel Χτυπημένο ή προβληματικό πάνελ.",
        "Transformer problem Πρόβλημα στον μετασχηματιστή.",
        "Ποιον ψάχνουμε; ιδιοκτήτες πάρκων, εταιρείες που διαχειρίζονται πάρκα, O&M companies, asset managers, τεχνικούς διευθυντές, εταιρείες με πολλά φωτοβολταϊκά έργα.",
        "Τι είναι Asset Manager; Asset Manager είναι ο άνθρωπος ή η εταιρεία που παρακολουθεί ένα επενδυτικό περιουσιακό στοιχείο. Στην περίπτωσή μας: το φωτοβολταϊκό πάρκο. Ο Asset Manager ενδιαφέρεται για πράγματα όπως: παραγωγή, κόστος, βλάβες, απόδοση, συμβάσεις, έσοδα.",
        "Τι ρωτά ο πωλητής; «Ποιος έχει σήμερα τη συντήρηση του πάρκου;» «Υπάρχει ενεργό συμβόλαιο O&M;» «Πότε έγινε η τελευταία προληπτική συντήρηση;» «Έχετε συχνές βλάβες;» «Υπάρχουν προβλήματα που επανέρχονται;» «Όταν υπάρχει βλάβη, σε πόσο χρόνο έρχεται τεχνικός;» «Χρειάζεστε δεύτερο συνεργάτη για έκτακτες ανάγκες;»",
        "Πολύ σημαντική ευκαιρία Ο πελάτης λέει: «Έχουμε ήδη εταιρεία συντήρησης.» Ο άπειρος πωλητής σκέφτεται: «Χάσαμε τη δουλειά.» Όχι. Ρωτάμε: «Καλύπτει όλες τις ανάγκες σας;» «Έχετε περιπτώσεις που χρειάζεστε επιπλέον συνεργείο;» «Καλύπτουν έκτακτες βλάβες;» «Υπάρχουν περιοχές όπου χρειάζεστε δεύτερο συνεργάτη;» Μπορεί να υπάρχει χώρος για: δεύτερο συνεργείο, έκτακτες επισκευές, συγκεκριμένες εργασίες, επιπλέον πάρκα.",
        "Η επανάληψη εδώ είναι πολύ σημαντική Αν κάνουμε σωστά μία δουλειά: ο πελάτης μπορεί να μας καλέσει ξανά. Και ξανά. Και ξανά. Άρα μία μικρή πρώτη επισκευή μπορεί να γίνει: μακροχρόνια συνεργασία συντήρησης.",
        "ΥΠΗΡΕΣΙΑ 07 Καθαρισμός και Συντήρηση Πάρκου Η ιστορία Το πάρκο δεν έχει καμία ηλεκτρική βλάβη. Όλα δουλεύουν. Αλλά με τον καιρό πάνω στα πάνελ μαζεύονται: σκόνη, χώμα, γύρη, περιττώματα πουλιών, άλλοι ρύποι. Κάτω και γύρω από τα πάνελ μπορεί να μεγαλώσουν: χόρτα, θάμνοι, βλάστηση. Αυτό μπορεί να δημιουργήσει προβλήματα.",
        "Γιατί καθαρίζουμε τα πάνελ; Τα πάνελ χρειάζονται: φως. Αν πάνω τους υπάρχει πολλή βρωμιά: λιγότερο φως φτάνει στα cells. Άρα: μπορεί να μειωθεί η παραγωγή.",
        "Τι είναι Soiling; Soiling σημαίνει: βρωμιά και ρύποι πάνω στην επιφάνεια του πάνελ. Μπορεί να είναι: σκόνη, χώμα, γύρη, άλατα, περιττώματα πουλιών.",
        "Ένα απλό παράδειγμα Έχεις ένα τζάμι. Αν είναι καθαρό: βλέπεις εύκολα μέσα. Αν γεμίσει χώμα: περνά λιγότερο φως. Κάτι αντίστοιχο συμβαίνει και στο πάνελ.",
        "Γιατί μας ενδιαφέρουν τα χόρτα; Δεν είναι μόνο θέμα εμφάνισης. Πολύ ψηλή βλάστηση μπορεί: να δημιουργεί σκιά, να δυσκολεύει την πρόσβαση των τεχνικών, να αυξάνει τον κίνδυνο πυρκαγιάς, να δυσκολεύει τον έλεγχο του πάρκου.",
        "Τι είναι Vegetation Management; Ο πελάτης μπορεί να πει: «Χρειαζόμαστε vegetation management.» Σημαίνει: διαχείριση της βλάστησης μέσα και γύρω από το πάρκο. Με πολύ απλά λόγια: να μην αφήνουμε το πάρκο να γεμίζει ανεξέλεγκτα με χόρτα και θάμνους.",
        "Πόσο συχνά γίνεται; Δεν υπάρχει μία απάντηση για όλα τα πάρκα. Εξαρτάται από: περιοχή, σκόνη, βροχές, βλάστηση, καιρό, εποχή, ανάγκες του πάρκου. Και εδώ βρίσκεται η μεγάλη εμπορική ευκαιρία: αυτή η υπηρεσία μπορεί να επαναλαμβάνεται. Ένα πάρκο μπορεί να χρειάζεται: καθαρισμό ξανά, κοπή χόρτων ξανά, περιοδική φροντίδα ξανά.",
        "Τι πρέπει να σκέφτεται ο πωλητής; Όχι: «Θα τους καθαρίσουμε μία φορά.» Αλλά: «Μπορούμε να οργανώσουμε σταθερό πρόγραμμα;» Παράδειγμα: αντί για μία δουλειά: «Καθαρισμός τον Ιούνιο.» μπορεί να γίνει συνεργασία: «Προγραμματισμένοι καθαρισμοί και φροντίδα πάρκου κάθε χρόνο.»",
        "Τι ρωτάμε; «Πόσα πάρκα διαχειρίζεστε;» Πολύ σημαντική ερώτηση. Γιατί μπορεί να μιλάμε όχι για ένα πάρκο αλλά για: 5, 10 ή 30 πάρκα.",
        "«Πότε έγινε ο τελευταίος καθαρισμός;» «Πόσο συχνά καθαρίζετε τα panels;» «Υπάρχει σταθερό πρόγραμμα ή γίνεται όταν χρειάζεται;» «Ποιος αναλαμβάνει τα χόρτα;» «Έχετε πρόβλημα με έντονη βλάστηση;» «Υπάρχει επόμενος προγραμματισμένος καθαρισμός;»",
        "Πολύ δυνατό εμπορικό σημάδι Ο πελάτης λέει: «Έχουμε 12 πάρκα.» Ο πωλητής δεν πρέπει να ρωτήσει μόνο: «Θέλετε να καθαρίσουμε αυτό το πάρκο;» Πρέπει να ρωτήσει: «Πώς οργανώνετε τον καθαρισμό και τη συντήρηση και στα 12 πάρκα;» Αυτό μπορεί να μετατρέψει: μία μικρή δουλειά σε: μεγάλο επαναλαμβανόμενο συμβόλαιο.",
        "ΥΠΗΡΕΣΙΑ 08 Έλεγχος Απόδοσης και Repowering Η ιστορία Το πάρκο λειτουργεί εδώ και χρόνια. Δεν έχει σταματήσει. Αλλά ο ιδιοκτήτης αρχίζει να παρατηρεί κάτι. Λέει: «Νομίζω ότι δεν παράγει όσο παλιά.» ή: «Έχουμε παλιό εξοπλισμό.» ή: «Θέλουμε να δούμε αν μπορούμε να βγάλουμε περισσότερη παραγωγή από το ίδιο πάρκο.» Εδώ ξεκινά η υπηρεσία 08.",
        "Τι σημαίνει απόδοση; Πολύ απλά: Πόσο καλά κάνει τη δουλειά του το πάρκο. Ένα πάρκο μπορεί: να λειτουργεί, αλλά να μην λειτουργεί όσο καλά θα μπορούσε. Αυτό είναι πολύ σημαντικό.",
        "Παράδειγμα Ένα αυτοκίνητο μπορεί να κινείται. Αλλά: να καίει πολύ καύσιμο, να έχει προβλήματα, να μην αποδίδει όπως παλιά. Δεν είναι τελείως χαλασμένο. Αλλά: χρειάζεται έλεγχο. Το ίδιο μπορεί να συμβεί σε ένα φωτοβολταϊκό πάρκο.",
        "Τι μπορεί να ελέγχεται; Η τεχνική ομάδα μπορεί να κοιτάξει: πόση ενέργεια παράγει, πόση θα έπρεπε να παράγει, αν υπάρχουν συχνές βλάβες, αν υπάρχουν απώλειες, αν τα panels έχουν υποβαθμιστεί, αν οι inverters είναι παλιοί, αν υπάρχει εξοπλισμός που δημιουργεί προβλήματα. Ο πωλητής δεν κάνει αυτούς τους υπολογισμούς. Πρέπει να ακούει τον πελάτη.",
        "Τι είναι Performance? Performance σημαίνει: απόδοση. Αν ο πελάτης λέει: «We have performance issues.» σημαίνει: «Το πάρκο δεν αποδίδει όπως θα θέλαμε.»",
        "Τι είναι Repowering; Πολύ σημαντική λέξη. Repowering σημαίνει: αναβαθμίζουμε ένα παλιότερο φωτοβολταϊκό πάρκο με νεότερο εξοπλισμό. Μπορεί να αλλάξουμε: panels, inverters, ηλεκτρικό εξοπλισμό, άλλα μέρη του συστήματος.",
        "Γιατί να κάνει κάποιος repowering; Παράδειγμα. Ένα πάρκο έχει παλιά panels: 250W. Σήμερα υπάρχουν πολύ ισχυρότερα panels. Ο ιδιοκτήτης σκέφτεται: «Έχω ήδη τον χώρο, την εγκατάσταση και το έργο. Μπορώ να το αναβαθμίσω;» Αυτή είναι η λογική.",
        "Repowering δεν σημαίνει ότι όλα είναι χαλασμένα Πολύ σημαντικό. Ένα panel μπορεί να λειτουργεί κανονικά. Αλλά να είναι παλιάς τεχνολογίας. Ο ιδιοκτήτης μπορεί να θέλει: μεγαλύτερη παραγωγή ή νεότερο εξοπλισμό. Άρα αφαιρεί panels που: μπορεί ακόμη να έχουν εμπορική αξία. Και εκεί υπάρχει τεράστια ευκαιρία για εμάς.",
        "Ένα Repowering μπορεί να δημιουργήσει πολλές δουλειές Ο πωλητής πρέπει να το μάθει αυτό απ' έξω. Όταν ακούει: REPOWERING δεν βλέπει μία δουλειά. Βλέπει πιθανώς:"
      ]
    ],
    [
      "8. Αγορά των παλιών panels",
      [
        "Αυτό μπορεί να γίνει πολύ μεγάλη εμπορική ευκαιρία.",
        "Η πιο σημαντική ερώτηση Όταν κάποιος πει: «Θα κάνουμε repowering.» ο πωλητής πρέπει να ρωτήσει: «Τι θα γίνει με τα παλιά panels;» Αυτή η ερώτηση πρέπει να γίνει αυτόματη.",
        "Άλλες σημαντικές ερωτήσεις «Πόσο μεγάλο είναι το πάρκο;» «Πόσα panels πρόκειται να αντικατασταθούν;» «Τι Watt είναι τα παλιά panels;» «Πότε θα ξεκινήσει το έργο;» «Ποιος θα αναλάβει την αποξήλωση;» «Έχει ήδη επιλεγεί νέος εξοπλισμός;» «Έχει ήδη αναλάβει κάποιος το έργο;»",
        "Εδώ υπάρχει και μελλοντική επανάληψη Ο έλεγχος απόδοσης δεν χρειάζεται να γίνεται μόνο μία φορά στη ζωή ενός πάρκου. Μπορεί να γίνεται περιοδικά. Άρα και εδώ μπορεί να δημιουργηθεί: σταθερή σχέση με τον πελάτη.",
        "ΥΠΗΡΕΣΙΑ 09 Αντικατάσταση Πάνελ και Εξοπλισμού Η ιστορία Έχουμε αποφασίσει ότι κάτι πρέπει να αλλάξει. Μπορεί να είναι: 20 χαλασμένα panels, 500 panels, 10.000 panels, ένας inverter, πολλοί inverters, άλλο ηλεκτρικό εξάρτημα. Τώρα πρέπει: το παλιό να βγει και το νέο να μπει.",
        "Γιατί γίνεται αντικατάσταση; Μπορεί να υπάρχει: Βλάβη Κάτι χάλασε. Repowering Θέλουμε νεότερη τεχνολογία. Hail damage Ζημιά από χαλάζι. Fire damage Ζημιά από φωτιά. Χαμηλή απόδοση Ο εξοπλισμός δεν αποδίδει καλά. Warranty replacement Ο κατασκευαστής αντικαθιστά προβληματικό εξοπλισμό μέσω εγγύησης.",
        "Τι μπορεί να περιλαμβάνει η δουλειά; αποξήλωση παλιών panels, αποξήλωση άλλου εξοπλισμού, τοποθέτηση νέων panels, αλλαγή inverters, νέες συνδέσεις, ηλεκτρολογικές προσαρμογές, τελικούς ελέγχους.",
        "Το πιο σημαντικό σημείο για τη MELAS ENERGEIAKI Ο παλιός εξοπλισμός δεν πρέπει να θεωρείται αυτόματα: σκουπίδι. Μπορεί να έχει: εμπορική αξία. Άρα σε κάθε αντικατάσταση ο πωλητής ρωτά: «Τι θα γίνει με τον εξοπλισμό που αφαιρείται;»",
        "Το μεγάλο λάθος Ο πελάτης λέει: «Αλλάζουμε 6.000 panels.» Ο πωλητής σκέφτεται: «Μπορούμε να αναλάβουμε την εγκατάσταση.» Σωστό. Αλλά λείπει το μισό opportunity. Πρέπει να σκεφτεί και: «Μπορούμε να αγοράσουμε τα 6.000 παλιά panels;» Έτσι μία συζήτηση μπορεί να δημιουργήσει: δύο διαφορετικές δουλειές.",
        "Πολύ σημαντικό: η αποξήλωση Η αξία των παλιών panels μπορεί να καταστραφεί αν γίνει κακή αποξήλωση. Δεν θέλουμε: panels να πετιούνται, frames να λυγίζουν, καλώδια να κόβονται χωρίς λόγο, connectors να σπάνε, panels να στοιβάζονται άτσαλα. Γιατί; Ένα panel μπορεί να λειτουργούσε τέλεια πριν το κατεβάσουν. Αλλά μετά από κακό handling: να έχει χάσει μεγάλο μέρος της αξίας του.",
        "Τι είναι Handling; Handling σημαίνει: ο τρόπος που πιάνουμε, μετακινούμε, φορτώνουμε και αποθηκεύουμε τον εξοπλισμό. Κακό handling: = ζημιές. Καλό handling: = προστασία της αξίας.",
        "Τι ρωτάει ο πωλητής; «Πόσα panels αλλάζετε;» «Τι μοντέλα είναι;» «Πόσα Watt;» «Γιατί αντικαθίστανται;» «Είναι ακόμη εγκατεστημένα;» «Πότε θα γίνει η αποξήλωση;» «Ποιος θα τα αποξηλώσει;» «Έχει αποφασιστεί τι θα γίνει με τα παλιά;»",
        "Η μεγάλη εικόνα των υπηρεσιών 06–09 06 – Συντήρηση & Επισκευές «Έχει κάτι πρόβλημα;» ↓ 07 – Καθαρισμός & Φροντίδα «Χρειάζεται το πάρκο τακτική φροντίδα;» ↓ 08 – Απόδοση & Repowering «Το πάρκο αποδίδει όσο καλά θα μπορούσε;» ↓ 09 – Αντικατάσταση «Χρειάζεται να αλλάξουμε κάτι;»",
        "Η λέξη που πρέπει να θυμάται ο πωλητής ΕΠΑΝΑΛΗΨΗ Σε αυτές τις υπηρεσίες έχουμε πολύ μεγάλη πιθανότητα επανάληψης. Ο ίδιος πελάτης μπορεί να χρειάζεται: καθαρισμό κάθε χρόνο, συντήρηση κάθε χρόνο, τεχνικούς ελέγχους, επισκευές όταν υπάρχει βλάβη, σταδιακή αντικατάσταση εξοπλισμού, βοήθεια και σε άλλα πάρκα που διαθέτει.",
        "Ένα απλό παράδειγμα Βρίσκουμε έναν πελάτη με: 15 φωτοβολταϊκά πάρκα. Αρχικά μας δίνει: μία μικρή επισκευή σε ένα πάρκο. Αν η δουλειά γίνει σωστά: μπορεί να μας δώσει: συντήρηση και άλλων πάρκων, καθαρισμούς, επισκευές, repowering, αντικαταστάσεις, παλιά panels προς αγορά. Άρα: ένα μικρό lead μπορεί να εξελιχθεί σε πολύ μεγάλο πελάτη.",
        "Ο πωλητής δεν σταματά μετά την πρώτη πώληση Αφού ολοκληρωθεί μία δουλειά: πρέπει να υπάρχει follow-up. Παράδειγμα: «Όλα πήγαν καλά με την εργασία;» και μετά: «Υπάρχει κάποια άλλη ανάγκη στα υπόλοιπα πάρκα σας;» ή: «Πότε προγραμματίζετε την επόμενη συντήρηση;» ή: «Υπάρχει κάποια άλλη εγκατάσταση που θα θέλατε να εξετάσουμε;»",
        "Αυτό λέγεται Cross-Selling Cross-selling σημαίνει: Έχω ήδη έναν πελάτη και του προσφέρω άλλη υπηρεσία που πραγματικά χρειάζεται. Παράδειγμα: Κάναμε επισκευή. Μετά μπορεί να χρειάζεται: καθαρισμό. Κάναμε καθαρισμό. Μπορεί να χρειάζεται: έλεγχο απόδοσης. Βρήκαμε χαμηλή απόδοση. Μπορεί να οδηγηθούμε σε: repowering. Το repowering μπορεί να οδηγήσει σε: αγορά παλιών panels.",
        "Ο κύκλος Συντήρηση ↓ Βρίσκουμε πρόβλημα ↓ Επισκευή ↓ Ελέγχουμε απόδοση ↓ Βλέπουμε ανάγκη αναβάθμισης ↓ Repowering ↓ Αλλαγή panels ↓ Αγορά παλιών panels Μία υπηρεσία μπορεί να οδηγήσει στην επόμενη.",
        "Τι πρέπει να θυμάται ο πωλητής 06 Έχει βλάβες ή χρειάζεται συντήρηση; 07 Χρειάζεται καθαρισμό και φροντίδα; 08 Αποδίδει όσο καλά θα έπρεπε; 09 Χρειάζεται αλλαγή εξοπλισμού; Και μετά: «Υπάρχει κάτι από τον παλιό εξοπλισμό που μπορούμε να αγοράσουμε;»",
        "Μικρή άσκηση Πελάτης 1 «Έχουμε έναν inverter που σταματά συχνά.» Πιθανή υπηρεσία: 06 – Τεχνική Συντήρηση και Επισκευές",
        "Πελάτης 2 «Τα panels έχουν γεμίσει σκόνη και τα χόρτα έχουν ψηλώσει.» Πιθανή υπηρεσία: 07 – Καθαρισμός και Συντήρηση Πάρκου",
        "Πελάτης 3 «Το πάρκο λειτουργεί αλλά η παραγωγή έχει πέσει.» Πιθανή υπηρεσία: 08 – Έλεγχος Απόδοσης",
        "Πελάτης 4 «Το πάρκο είναι 12 ετών και εξετάζουμε να βάλουμε νέα panels.» Πιθανές υπηρεσίες: 08 – Repowering 09 – Αντικατάσταση εξοπλισμού και πιθανώς: Αγορά των παλιών panels",
        "Πελάτης 5 «Έχουμε 20 πάρκα και ψάχνουμε καλύτερη οργάνωση συντήρησης.» Αυτό δεν είναι απλώς ένα lead. Μπορεί να είναι: μεγάλος επαναλαμβανόμενος πελάτης.",
        "Τελικό μάθημα Στις υπηρεσίες 06–09 ο στόχος δεν είναι μόνο: να πάρουμε μία δουλειά. Ο πραγματικός στόχος είναι: να γίνουμε συνεργάτης που ο πελάτης θα καλεί ξανά όταν χρειάζεται κάτι. Γιατί ένα φωτοβολταϊκό πάρκο δεν σταματά να έχει ανάγκες επειδή ολοκληρώθηκε η κατασκευή του. Όσο λειτουργεί: δημιουργούνται νέες ανάγκες. Και όπου υπάρχει πραγματική ανάγκη: υπάρχει νέα εμπορική ευκαιρία."
      ]
    ]
  ],
  "me-special-services": [
    [
      "Αναλυτική μελέτη από το εκπαιδευτικό εγχειρίδιο",
      [
        "Μάθημα 6 – Υπηρεσίες 10 και 11 Με αυτό το μάθημα ολοκληρώνουμε την εκπαίδευση πάνω στις υπηρεσίες της εταιρείας. Θα δούμε: 10 – Αγοραπωλησίες Φωτοβολταϊκών Πάρκων 11 – Οικιακά Φωτοβολταϊκά Συστήματα",
        "ΥΠΗΡΕΣΙΑ 10 Αγοραπωλησίες Φωτοβολταϊκών Πάρκων Τι σημαίνει; Ένα φωτοβολταϊκό πάρκο δεν είναι μόνο πάνελ και καλώδια. Είναι και: μία επένδυση. Ο ιδιοκτήτης έχει επενδύσει χρήματα για να το κατασκευάσει. Το πάρκο παράγει ηλεκτρική ενέργεια. Από αυτή την παραγωγή μπορεί να δημιουργεί έσοδα. Άρα ολόκληρο το πάρκο μπορεί: να πουληθεί σε άλλον επενδυτή.",
        "Ένα απλό παράδειγμα Ο κύριος Γιώργος έχει ένα φωτοβολταϊκό πάρκο 2 MW. Το πάρκο λειτουργεί εδώ και 7 χρόνια. Ο κύριος Γιώργος αποφασίζει: «Θέλω να πουλήσω την επένδυσή μου.» Ένας άλλος επενδυτής λέει: «Θέλω να αγοράσω ένα έτοιμο φωτοβολταϊκό πάρκο που ήδη λειτουργεί.» Η MELAS ENERGEIAKI μπορεί να βοηθήσει να συναντηθούν: ο πραγματικός πωλητής και ο πραγματικός αγοραστής.",
        "Γιατί κάποιος πουλά ένα πάρκο; Μπορεί: να θέλει να πάρει τα χρήματά του και να επενδύσει αλλού, να αλλάζει επιχειρηματική στρατηγική, να πουλά ολόκληρο χαρτοφυλάκιο έργων, να χρειάζεται ρευστότητα, να έχει αποφασίσει ότι δεν θέλει πλέον να διαχειρίζεται το έργο. Δεν σημαίνει απαραίτητα ότι το πάρκο έχει πρόβλημα.",
        "Γιατί κάποιος αγοράζει έτοιμο πάρκο; Γιατί μπορεί να θέλει: επένδυση που ήδη λειτουργεί, ήδη υπάρχουσα παραγωγή, να αποφύγει όλη τη διαδικασία δημιουργίας έργου από το μηδέν, να αυξήσει το χαρτοφυλάκιό του.",
        "Τι πρέπει να ξέρουμε για το πάρκο; Δεν αρκεί να μας πει κάποιος: «Πωλείται φωτοβολταϊκό πάρκο.» Χρειαζόμαστε συγκεκριμένες πληροφορίες."
