    [
      "11. Πόσο ζητά ο πωλητής;",
      [
        "Αυτό λέγεται: Asking Price Asking Price σημαίνει: η τιμή που ζητά ο ιδιοκτήτης για να πουλήσει. Παράδειγμα: «The asking price is €1.500.000.» Δηλαδή: Ο ιδιοκτήτης ζητά 1,5 εκατομμύριο ευρώ.",
        "Προσοχή Asking price δεν σημαίνει: τελική αξία. Σημαίνει μόνο: πόσα ζητά ο seller. Ο αγοραστής μπορεί να θεωρεί ότι το πάρκο αξίζει λιγότερο.",
        "Due Diligence Θα ακουστεί συχνά. Με απλά λόγια: Due Diligence = πολύ προσεκτικός έλεγχος πριν αγοράσεις. Όπως πριν αγοράσεις ένα σπίτι: δεν κοιτάς μόνο αν είναι όμορφο. Θέλεις να ξέρεις: σε ποιον ανήκει, αν υπάρχουν προβλήματα, αν υπάρχουν χρέη, αν υπάρχουν σωστά έγγραφα, αν έχει τεχνικές ζημιές. Το ίδιο γίνεται και με ένα φωτοβολταϊκό πάρκο.",
        "Τι μπορεί να ελέγχεται; Τεχνικά Το πάρκο είναι σε καλή κατάσταση; Οικονομικά Τι έσοδα και έξοδα έχει; Νομικά Είναι όλα τα δικαιώματα και οι συμβάσεις σωστά; Φορολογικά Υπάρχουν υποχρεώσεις που πρέπει να εξεταστούν; Ο πωλητής δεν κάνει αυτούς τους ελέγχους. Τους κάνουν οι κατάλληλοι επαγγελματίες.",
        "Data Room Άλλη σημαντική λέξη. Data Room σημαίνει: ένας οργανωμένος ψηφιακός φάκελος με τα σημαντικά έγγραφα του έργου. Μπορεί να περιέχει: συμβάσεις, άδειες, παραγωγή, οικονομικά στοιχεία, τεχνικά στοιχεία, ασφαλιστήρια, έγγραφα γης, άλλα στοιχεία.",
        "Γιατί είναι σημαντικό; Αν ένας seller μας λέει: «Το Data Room είναι έτοιμο.» σημαίνει ότι πιθανότατα: έχει οργανώσει ήδη τα στοιχεία του έργου και ίσως είναι σοβαρός για πώληση.",
        "Το μεγάλο πρόβλημα στους μεσάζοντες Κάποιος τηλεφωνεί: «Ξέρω ένα πάρκο που πωλείται.» Αυτό δεν σημαίνει: ότι έχει πραγματικά το δικαίωμα να το πουλήσει. Μπορεί να το έχει ακούσει: από φίλο, που το άκουσε από κάποιον άλλο.",
        "Άρα τι ψάχνουμε; Θέλουμε να φτάσουμε: όσο πιο κοντά γίνεται στον πραγματικό ιδιοκτήτη ή στον εξουσιοδοτημένο εκπρόσωπο.",
        "Τι ρωτά ο πωλητής; «Είστε ο ιδιοκτήτης του έργου;» Αν όχι: «Ποια είναι ακριβώς η σχέση σας με τον ιδιοκτήτη;» «Έχετε εξουσιοδότηση για τη συγκεκριμένη πώληση;»",
        "Πολύ σημαντικό Qualified Lead Ένας καλός lead για πώληση πάρκου πρέπει να έχει: πραγματικό έργο, συγκεκριμένο ιδιοκτήτη, πραγματική πρόθεση πώλησης, βασικά στοιχεία έργου, πιθανό asking price, υπεύθυνο επικοινωνίας. Όχι: «Άκουσα ότι ίσως πωλείται.»",
        "Τι ρωτάμε; «Πού βρίσκεται το πάρκο;» «Πόσα MW είναι;» «Είναι σε λειτουργία;» «Πότε κατασκευάστηκε;» «Ποιος είναι ο ιδιοκτήτης;» «Υπάρχει πραγματική απόφαση πώλησης;» «Ποιο είναι το asking price;» «Υπάρχει διαθέσιμο Data Room;» «Η γη είναι ιδιόκτητη ή νοικιασμένη;» «Ποιος είναι ο κατάλληλος άνθρωπος για να συνεχίσουμε τη συζήτηση;»",
        "ΥΠΗΡΕΣΙΑ 11 Οικιακά Φωτοβολταϊκά Συστήματα Τώρα αφήνουμε τα μεγάλα πάρκα. Πηγαίνουμε: στο σπίτι.",
        "Η ιστορία Ένας ιδιοκτήτης σπιτιού λαμβάνει υψηλούς λογαριασμούς ηλεκτρικού ρεύματος. Έχει μεγάλη ταράτσα. Λέει: «Μπορώ να βάλω φωτοβολταϊκά και να χρησιμοποιώ την ενέργεια που παράγω;» Αυτό είναι ένα οικιακό φωτοβολταϊκό σύστημα.",
        "Τι θέλει συνήθως ο πελάτης; Συνήθως θέλει: μικρότερο κόστος ρεύματος, να παράγει δική του ενέργεια, μεγαλύτερη ενεργειακή ανεξαρτησία, πιθανώς μπαταρία.",
        "Πού μπορεί να μπει; Συχνά: σε ταράτσα, σε κεραμοσκεπή, σε διαθέσιμο χώρο του ακινήτου. Αλλά πριν πούμε ότι γίνεται: πρέπει να ελεγχθεί ο χώρος.",
        "Τι πρέπει να εξετάζεται; Χώρος Υπάρχει αρκετή επιφάνεια; Ήλιος Υπάρχει καλή έκθεση στον ήλιο; Σκιά Υπάρχουν: δέντρα, άλλα κτίρια, καμινάδες, άλλες κατασκευές; Στέγη Είναι κατάλληλη; Κατανάλωση Πόσο ρεύμα χρησιμοποιεί ο πελάτης; Ηλεκτρική εγκατάσταση Είναι κατάλληλη για το νέο σύστημα;",
        "Γιατί ρωτάμε την κατανάλωση; Γιατί δεν θέλουμε να σχεδιάσουμε ένα σύστημα στα τυφλά. Παράδειγμα: Οικογένεια Α: πολύ μικρή κατανάλωση. Οικογένεια Β: ηλεκτρικό αυτοκίνητο, αντλία θερμότητας, πολλά κλιματιστικά. Οι δύο οικογένειες: δεν έχουν τις ίδιες ανάγκες.",
        "Τι ζητάμε από τον πελάτη; Πολύ χρήσιμο: πρόσφατους λογαριασμούς ηλεκτρικού ρεύματος. Έτσι η τεχνική ομάδα μπορεί να δει καλύτερα: την πραγματική κατανάλωση.",
        "Τι είναι αυτοκατανάλωση; Πολύ απλά: παράγω ηλεκτρική ενέργεια και τη χρησιμοποιώ στο δικό μου σπίτι. Παράδειγμα: Είναι μεσημέρι. Τα panels παράγουν ρεύμα. Το σπίτι λειτουργεί: ψυγείο, κλιματιστικό, υπολογιστές. Μέρος της ενέργειας που παράγεται: χρησιμοποιείται άμεσα από το σπίτι.",
        "Τι γίνεται όταν υπάρχει περισσότερη παραγωγή από κατανάλωση; Αυτό εξαρτάται από το πώς έχει σχεδιαστεί το σύστημα και το ισχύον πλαίσιο. Μπορεί να υπάρχει: διαχείριση πλεονάζουσας ενέργειας, αποθήκευση, διαφορετικός τρόπος συμψηφισμού ή διάθεσης. Ο πωλητής: δεν υπόσχεται μόνος του τι ακριβώς θα γίνει. Η τεχνική ομάδα εξετάζει την περίπτωση.",
        "Μπαταρία Ο πελάτης μπορεί να πει: «Θέλω και battery.» Battery σημαίνει: μπαταρία αποθήκευσης ενέργειας.",
