        "Αν έχει κλείσει Σεβόμαστε. «Κατανοητό. Έχετε άλλες αντικαταστάσεις ή repowering που προγραμματίζονται στο μέλλον;»",
        "Αν δεν έχει κλείσει «Θα είχε νόημα να αξιολογήσουμε και εμείς το stock ώστε να έχετε μία επιπλέον επιλογή;» Απλό.",
        "ΑΝΤΙΡΡΗΣΗ 11 «ΕΧΟΥΜΕ ΚΑΛΥΤΕΡΗ ΠΡΟΣΦΟΡΑ» Δεν μπαίνουμε αμέσως σε πόλεμο τιμών. Ρωτάμε: «Η προσφορά είναι ήδη οριστική και δεσμευτική ή ακόμη αξιολογείτε επιλογές;»",
        "Γιατί; Μπορεί η άλλη προσφορά: να μην έχει κλείσει, να έχει διαφορετικούς όρους, να περιλαμβάνει προκαταβολές, να έχει προβλήματα logistics. Δεν συγκρίνουμε μόνο αριθμό.",
        "Μπορούμε να πούμε «Αν είστε ακόμη στη διαδικασία αξιολόγησης, μπορούμε να εξετάσουμε το stock και να σας δώσουμε τη δική μας πρόταση.»",
        "ΑΝΤΙΡΡΗΣΗ 12 «ΠΟΣΟ ΔΙΝΕΤΕ ΑΝΑ PANEL;» Πολύ συνηθισμένο. Δεν απαντάμε χωρίς στοιχεία.",
        "Απάντηση «Δεν θέλω να σας δώσω έναν τυχαίο αριθμό. Η τιμή εξαρτάται από Watt, μοντέλο, κατάσταση, ποσότητα, διαστάσεις, τοποθεσία και logistics.» Και: «Αν μας στείλετε φωτογραφίες μπροστά, πίσω και του label, μπορούμε να κάνουμε σωστή αξιολόγηση.»",
        "Αν πιέζει «Δώστε μου έστω μία τιμή.» Απάντηση: «Θα ήταν παραπλανητικό να σας δώσω τιμή χωρίς να γνωρίζω το stock. Προτιμώ να σας πω κάτι σωστό αφού έχουμε τα βασικά στοιχεία.» Αυτό δείχνει επαγγελματισμό.",
        "ΑΝΤΙΡΡΗΣΗ 13 «ΠΟΣΟ ΧΡΕΩΝΕΤΕ ΓΙΑ ΤΗΝ ΥΠΗΡΕΣΙΑ;» Το ίδιο. Δεν δίνουμε τυφλή τιμή. Λέμε: «Εξαρτάται από το μέγεθος του έργου, την τοποθεσία και τις εργασίες που χρειάζονται. Αν μου δώσετε λίγες βασικές πληροφορίες, μπορούμε να σας ετοιμάσουμε σωστή πρόταση.»",
        "Μετά discovery «Πόσα MW είναι το πάρκο;» «Πού βρίσκεται;» «Τι ακριβώς χρειάζεστε;» «Πότε θέλετε να γίνει;»",
        "ΑΝΤΙΡΡΗΣΗ 14 «ΕΙΣΤΕ ΑΚΡΙΒΟΙ» Πολύ σημαντικό. Πρώτα δεν αμυνόμαστε. Λέμε: «Κατανοητό.» Μετά: «Σε σχέση με ποια λύση ή προσφορά το συγκρίνετε;»",
        "Γιατί αυτή η ερώτηση; Γιατί μπορεί να συγκρίνει: δύο τελείως διαφορετικά πράγματα. Παράδειγμα: η μία προσφορά περιλαμβάνει: εργασία, εξοπλισμό, μεταφορά, εγγύηση. Η άλλη: μόνο εργασία. Άρα πρώτα καταλαβαίνουμε.",
        "Άλλη απάντηση «Ποιο κομμάτι της προσφοράς θεωρείτε υψηλό;» Τώρα ο πελάτης θα μας πει τι πραγματικά τον ενοχλεί.",
        "ΑΝΤΙΡΡΗΣΗ 15 «ΘΕΛΩ ΕΚΠΤΩΣΗ» Δεν δίνει ο πωλητής μόνος του έκπτωση. Λέει: «Μπορώ να μεταφέρω το αίτημά σας και να δούμε τι δυνατότητα υπάρχει, αλλά πρώτα θέλω να καταλάβω αν όλα τα υπόλοιπα σημεία της πρότασης σας καλύπτουν.» Πολύ σημαντικό. Γιατί μπορεί ο πελάτης να ζητά έκπτωση: χωρίς να έχει αποφασίσει καν αν θέλει να αγοράσει.",
        "Καλή ερώτηση «Αν λυνόταν το θέμα της τιμής, θα ήσασταν έτοιμοι να προχωρήσετε;» Αν πει: «Όχι, έχουμε και άλλα θέματα.» τότε η τιμή δεν είναι η πραγματική αντίρρηση.",
        "ΑΝΤΙΡΡΗΣΗ 16 «ΔΕΝ ΕΧΟΥΜΕ BUDGET» Budget σημαίνει: διαθέσιμα χρήματα για τη συγκεκριμένη εργασία. Ρωτάμε: «Δεν υπάρχει budget αυτή τη στιγμή ή δεν έχει εγκριθεί ακόμη;» Μεγάλη διαφορά.",
        "Αν δεν έχει εγκριθεί Ρωτάμε: «Πότε γίνεται συνήθως η έγκριση;» Τώρα έχουμε follow-up.",
        "Αν πραγματικά δεν υπάρχει Μπορούμε να ρωτήσουμε: «Είναι κάτι που μπορεί να μπει στον επόμενο προϋπολογισμό;»",
        "ΑΝΤΙΡΡΗΣΗ 17 «ΔΕΝ ΕΙΣΤΕ ΓΝΩΣΤΗ ΕΤΑΙΡΕΙΑ» Πιθανή αντίρρηση ειδικά στην αρχή. Δεν προσβάλλουμε τον πελάτη. Δεν λέμε: «Μα είμαστε πολύ μεγάλη εταιρεία.» αν δεν ισχύει.",
        "Απάντηση «Το καταλαβαίνω. Είναι λογικό πριν συνεργαστείτε με μία νέα εταιρεία να θέλετε να δείτε περισσότερα στοιχεία. Μπορούμε να σας παρουσιάσουμε την εταιρεία, το αντικείμενό μας και τον τρόπο με τον οποίο οργανώνουμε το έργο.»",
        "Αν υπάρχει κατάλληλο reference Μπορεί να δοθεί. Αλλά μόνο: πραγματικό reference. Ποτέ φανταστικό.",
        "ΑΝΤΙΡΡΗΣΗ 18 «ΔΕΝ ΣΑΣ ΓΝΩΡΙΖΩ» Απάντηση: «Απολύτως λογικό. Γι' αυτό στην αρχή δεν σας ζητάω να αποφασίσετε κάτι. Θέλω πρώτα να δούμε αν υπάρχει πραγματικό σημείο συνεργασίας.» Πολύ ήρεμη απάντηση.",
        "ΑΝΤΙΡΡΗΣΗ 19 «ΠΟΙΟΙ ΠΕΛΑΤΕΣ ΣΑΣ ΕΧΟΥΝ ΣΥΝΕΡΓΑΣΤΕΙ;» Λέμε μόνο: αληθινά, εγκεκριμένα, κατάλληλα references. Δεν αποκαλύπτουμε εμπιστευτικές πληροφορίες. Δεν φουσκώνουμε.",
        "ΑΝΤΙΡΡΗΣΗ 20 «ΕΧΕΤΕ ΚΑΝΕΙ ΠΟΤΕ ΤΕΤΟΙΟ ΕΡΓΟ;» Αν ναι: λέμε την αλήθεια. Αν όχι: δεν λέμε ψέματα. Μπορούμε να πούμε: «Για το συγκεκριμένο ακριβώς scope θα χρειαστεί να το επιβεβαιώσω με την τεχνική ομάδα ώστε να σας δώσω σωστή εικόνα.»",
        "ΑΝΤΙΡΡΗΣΗ 21 «ΜΠΟΡΕΙΤΕ ΝΑ ΤΟ ΚΑΝΕΤΕ ΣΕ 10 ΗΜΕΡΕΣ;» Ο πωλητής δεν υπόσχεται. Απάντηση: «Θα χρειαστεί να ελέγξουμε διαθεσιμότητα συνεργείου, μέγεθος έργου και scope πριν δεσμευτούμε σε χρόνο.»",
        "ΑΝΤΙΡΡΗΣΗ 22 «ΘΕΛΩ ΕΓΓΥΗΣΗ ΟΤΙ ΘΑ ΠΑΡΑΓΕΙ Χ% ΠΕΡΙΣΣΟΤΕΡΟ» Δεν υπόσχεται ο πωλητής. Λέει: «Αυτό χρειάζεται τεχνική αξιολόγηση. Δεν θα ήταν σωστό να σας υποσχεθώ ποσοστό χωρίς να εξεταστεί το έργο.»",
        "ΑΝΤΙΡΡΗΣΗ 23 «ΔΕΝ ΘΕΛΩ ΝΑ ΣΑΣ ΔΩΣΩ ΣΤΟΙΧΕΙΑ» Σεβόμαστε. Λέμε: «Φυσικά. Μπορούμε να ξεκινήσουμε μόνο με τα απολύτως βασικά και να προχωρήσουμε στα υπόλοιπα όταν υπάρχει πραγματικό ενδιαφέρον.»",
        "Δεν πιέζουμε για οικονομικά, τεχνικά, προσωπικά, εμπιστευτικά στοιχεία, αν δεν υπάρχει λόγος.",
        "ΑΝΤΙΡΡΗΣΗ 24 «ΣΤΕΙΛΤΕ NDA ΠΡΩΤΑ» NDA σημαίνει: συμφωνία εμπιστευτικότητας. Αυτό μπορεί να είναι θετικό σημάδι. Δείχνει ότι ίσως υπάρχουν: σοβαρές πληροφορίες. Λέμε: «Βεβαίως. Θα το μεταφέρω ώστε να προχωρήσουμε σωστά.» Δεν υπογράφει ο πωλητής μόνος του κάτι χωρίς έγκριση.",
        "ΑΝΤΙΡΡΗΣΗ 25 «ΘΕΛΩ ΝΑ ΜΙΛΗΣΩ ΜΕ ΤΟΝ ΜΗΧΑΝΙΚΟ» Αν υπάρχει ήδη σοβαρή ευκαιρία: πολύ καλό. Λέμε: «Βεβαίως. Για να προετοιμάσουμε σωστά τη συζήτηση, μπορείτε να μου πείτε ποιο είναι το βασικό τεχνικό θέμα που θέλετε να εξετάσετε;»",
        "Γιατί; Έτσι ο μηχανικός μας μπαίνει: προετοιμασμένος.",
        "ΑΝΤΙΡΡΗΣΗ 26 «ΔΕΝ ΘΕΛΩ ΝΑ ΜΙΛΗΣΩ ΜΕ ΠΩΛΗΤΗ» Δεν προσβαλλόμαστε. Μπορούμε να πούμε: «Το καταλαβαίνω. Ο δικός μου ρόλος είναι κυρίως να καταλάβω αν υπάρχει πραγματική ανάγκη και, αν υπάρχει, να σας φέρω στον σωστό άνθρωπο της ομάδας.» Πολύ σωστό για τον δικό μας ρόλο.",
        "ΑΝΤΙΡΡΗΣΗ 27 «ΣΤΕΙΛΤΕ ΜΟΥ ΠΡΩΤΑ ΕΤΑΙΡΙΚΗ ΠΑΡΟΥΣΙΑΣΗ» Λέμε: «Φυσικά. Να σας ρωτήσω μόνο ποιο κομμάτι είναι πιο σχετικό για εσάς ώστε να σας στείλω τα σωστά στοιχεία;» Έτσι συνεχίζουμε discovery χωρίς πίεση.",
        "ΑΝΤΙΡΡΗΣΗ 28 «ΔΕΝ ΑΛΛΑΖΟΥΜΕ ΠΡΟΜΗΘΕΥΤΕΣ» Απάντηση: «Κατανοητό. Δεν επικοινωνώ απαραίτητα για να αντικαταστήσετε κάποιον. Θα μπορούσαμε να αποτελέσουμε μία επιπλέον επιλογή αν χρειαστείτε δεύτερη πηγή ή επιπλέον δυναμικότητα.»",
        "Τι σημαίνει δεύτερη πηγή; Αν ένας προμηθευτής: δεν έχει stock, καθυστερεί, δεν μπορεί να αναλάβει άλλο project, ο πελάτης έχει εναλλακτική.",
        "ΑΝΤΙΡΡΗΣΗ 29 «ΔΕΝ ΧΡΕΙΑΖΟΜΑΣΤΕ BACKUP» Απάντηση: «Κατανοητό. Τότε θα είχε νόημα απλώς να παραμείνουμε σε επαφή για κάποιο μελλοντικό project που δεν καλύπτεται από την υπάρχουσα συνεργασία σας.» Και σταματάμε.",
        "ΑΝΤΙΡΡΗΣΗ 30 «ΕΧΟΥΜΕ ΣΥΜΒΟΛΑΙΟ ΓΙΑ 3 ΧΡΟΝΙΑ» Απάντηση: «Κατανοητό. Γνωρίζετε πότε περίπου λήγει ή πότε γίνεται η επόμενη αξιολόγηση συνεργατών;» Τώρα έχουμε ημερομηνία.",
        "Πολύ σημαντικό Δεν προσπαθούμε: να παραβιάσει το συμβόλαιο. Θέλουμε: να είμαστε εκεί όταν ανοίξει η επόμενη ευκαιρία.",
        "ΑΝΤΙΡΡΗΣΗ 31 «ΚΑΝΟΥΜΕ TENDER» Tender σημαίνει: οργανωμένη διαδικασία προσφορών. Αυτό μπορεί να είναι εξαιρετική πληροφορία. Ρωτάμε: «Πότε ανοίγει η επόμενη διαδικασία;» «Πώς μπορεί μία νέα εταιρεία να συμμετάσχει;» «Ποιος διαχειρίζεται το procurement;»",
        "Ο στόχος Δεν είναι πάντα: να πάρουμε τη δουλειά σήμερα. Μπορεί να είναι: να μπούμε στη λίστα προμηθευτών για τον επόμενο διαγωνισμό.",
        "ΑΝΤΙΡΡΗΣΗ 32 «ΔΕΝ ΕΙΣΤΕ ΣΤΗ VENDOR LIST» Vendor list = λίστα εγκεκριμένων προμηθευτών. Ρωτάμε: «Ποια είναι η διαδικασία ώστε μία νέα εταιρεία να αξιολογηθεί και να προστεθεί;» Τώρα η αντίρρηση έγινε: συγκεκριμένο επόμενο βήμα.",
        "ΑΝΤΙΡΡΗΣΗ 33 «ΧΡΕΙΑΖΕΤΑΙ ΠΙΣΤΟΠΟΙΗΣΗ» Δεν λέμε: «Την έχουμε.» αν δεν ξέρουμε. Λέμε: «Ποια ακριβώς πιστοποίηση απαιτείται; Θα το ελέγξω με την ομάδα μας.»",
        "ΑΝΤΙΡΡΗΣΗ 34 «ΔΕΝ ΘΕΛΟΥΜΕ ΠΡΟΚΑΤΑΒΟΛΗ / ΘΕΛΟΥΜΕ ΣΥΓΚΕΚΡΙΜΕΝΟΥΣ ΟΡΟΥΣ» Οι εμπορικοί όροι δεν αποφασίζονται από τον πωλητή χωρίς έγκριση. Λέμε: «Κατανοητό. Θα καταγράψω τον όρο σας ώστε να εξεταστεί στην εμπορική πρόταση.»",
        "ΑΝΤΙΡΡΗΣΗ 35 «ΘΑ ΣΑΣ ΠΑΡΟΥΜΕ ΕΜΕΙΣ» Πολύ συχνό. Μην αφήνουμε όλο το follow-up στον πελάτη. Λέμε: «Φυσικά. Για να μην σας μείνει όμως σαν εκκρεμότητα, να σας καλέσω εγώ την επόμενη εβδομάδα;»",
        "ΑΝΤΙΡΡΗΣΗ 36 «ΔΕΝ ΕΧΩ ΑΠΟΦΑΣΙΣΕΙ ΑΚΟΜΗ» Απάντηση: «Φυσικά. Τι είναι αυτό που πρέπει να ξεκαθαρίσει πριν πάρετε απόφαση;» Πολύ δυνατή ερώτηση. Μπορεί να απαντήσει: τιμή, τεχνικό θέμα, budget, διοίκηση, άλλο offer. Τώρα ξέρουμε την πραγματική αιτία.",
        "ΑΝΤΙΡΡΗΣΗ 37 «ΠΡΕΠΕΙ ΝΑ ΡΩΤΗΣΩ ΤΟΝ ΔΙΕΥΘΥΝΤΗ» Απάντηση: «Βεβαίως. Τι πληροφορίες θα χρειαστεί για να μπορέσει να το αξιολογήσει;» και: «Θα είχε νόημα να κάνουμε μία σύντομη συζήτηση όλοι μαζί;»",
        "Γιατί; Για να μη γίνει το εξής: Εμείς → άνθρωπος Α → διευθυντής → λάθος πληροφορία. Καλύτερα: να μιλήσουμε με τον πραγματικό decision maker.",
        "ΑΝΤΙΡΡΗΣΗ 38 «ΠΡΕΠΕΙ ΝΑ ΤΟ ΣΥΖΗΤΗΣΩ ΜΕ ΤΗΝ ΟΜΑΔΑ» Ρωτάμε: «Ποιοι άλλοι συμμετέχουν στην απόφαση;» Αυτή είναι πολύ σημαντική B2B ερώτηση. Γιατί μπορεί να χρειάζονται: Technical Manager, Procurement, CFO, CEO.",
        "ΑΝΤΙΡΡΗΣΗ 39 «ΔΕΝ ΕΙΜΑΙ ΕΓΩ Ο ΥΠΕΥΘΥΝΟΣ» Τέλεια. Δεν σπαταλάμε χρόνο. Λέμε: «Ευχαριστώ. Ποιος είναι ο κατάλληλος άνθρωπος για αυτό το θέμα;» και: «Θα μπορούσα να έχω το όνομα ή το email του;»",
        "ΑΝΤΙΡΡΗΣΗ 40 «ΔΕΝ ΜΠΟΡΩ ΝΑ ΣΑΣ ΔΩΣΩ ΤΟ ΟΝΟΜΑ» Σεβόμαστε. Ρωτάμε: «Ποιο τμήμα πρέπει να ζητήσω;» Τουλάχιστον: μαθαίνουμε κατεύθυνση.",
        "ΑΝΤΙΡΡΗΣΗ 41 «ΔΕΝ ΚΑΝΟΥΜΕ REPOWERING» Απάντηση: «Κατανοητό. Κάνετε όμως αντικαταστάσεις panels λόγω βλαβών ή συντήρησης;» Μπορεί να μην κάνει full repowering. Αλλά να αλλάζει: πολλά panels κάθε χρόνο.",
        "ΑΝΤΙΡΡΗΣΗ 42 «ΔΕΝ ΠΟΥΛΑΜΕ ΤΑ ΠΑΛΙΑ PANELS» Ρωτάμε: «Τι κάνετε συνήθως με αυτά όταν αφαιρούνται;» Μπορεί να: αποθηκεύονται, ανακυκλώνονται, επιστρέφουν σε supplier, μένουν στο site. Αυτή η πληροφορία έχει αξία.",
        "ΑΝΤΙΡΡΗΣΗ 43 «ΤΑ ΠΑΝΕΛ ΕΙΝΑΙ ΠΟΛΥ ΠΑΛΙΑ» Δεν απορρίπτουμε τηλεφωνικά. Ρωτάμε: «Πόσα Watt είναι περίπου και σε τι κατάσταση βρίσκονται;» Μπορεί να είναι κατάλληλα για τη δική μας αγορά.",
        "ΑΝΤΙΡΡΗΣΗ 44 «ΔΕΝ ΕΧΟΥΜΕ ΦΩΤΟΓΡΑΦΙΕΣ» Απάντηση: «Δεν υπάρχει πρόβλημα. Όταν υπάρχει δυνατότητα, θα χρειαστούμε μερικές απλές φωτογραφίες μπροστά, πίσω και του label για να γίνει πρώτη αξιολόγηση.» Κλείνουμε follow-up.",
        "ΑΝΤΙΡΡΗΣΗ 45 «ΔΕΝ ΞΕΡΩ ΤΟ ΜΟΝΤΕΛΟ» Ρωτάμε: «Υπάρχει δυνατότητα να μας στείλετε μία φωτογραφία της ετικέτας πίσω από το panel;» Το label θα μας πει πολλά.",
        "ΑΝΤΙΡΡΗΣΗ 46 «ΔΕΝ ΞΕΡΩ ΠΟΣΑ ΕΙΝΑΙ» Δεν χρειάζεται πάντα ακριβής αριθμός στην πρώτη κλήση. Ρωτάμε: «Μιλάμε περίπου για εκατοντάδες ή για χιλιάδες panels;» Παίρνουμε τουλάχιστον κλίμακα.",
        "ΑΝΤΙΡΡΗΣΗ 47 «ΔΕΝ ΕΧΕΙ ΑΠΟΦΑΣΙΣΤΕΙ ΑΚΟΜΑ ΤΙ ΘΑ ΓΙΝΕΙ ΜΕ ΤΑ PANELS» Πολύ καλό. Μπορεί να υπάρχει χώρος για εμάς. Λέμε: «Τότε θα είχε νόημα να τα αξιολογήσουμε πριν πάρετε τελική απόφαση.»",
        "ΑΝΤΙΡΡΗΣΗ 48 «ΔΕΝ ΘΕΛΟΥΜΕ ΜΕΣΑΖΟΝΤΕΣ» Δεν προσποιούμαστε κάτι άλλο. Λέμε ξεκάθαρα τι κάνουμε. Αν εμείς είμαστε ο πραγματικός αγοραστής: «Το καταλαβαίνω. Στην περίπτωση των panels, η MELAS ENERGEIAKI εξετάζει την αγορά του stock απευθείας.» Αν πρόκειται για υπηρεσία: εξηγούμε τον πραγματικό μας ρόλο.",
        "ΑΝΤΙΡΡΗΣΗ 49 «ΘΕΛΟΥΜΕ ΜΟΝΟ ΜΕΓΑΛΕΣ ΕΤΑΙΡΕΙΕΣ» Απάντηση: «Το καταλαβαίνω. Ποια είναι τα βασικά κριτήρια που ζητάτε από έναν συνεργάτη ώστε να αξιολογηθεί;» Τώρα μαθαίνουμε: τι πρέπει να αποδείξουμε.",
        "ΑΝΤΙΡΡΗΣΗ 50 «ΔΕΝ ΔΟΥΛΕΥΟΥΜΕ ΜΕ ΝΕΟΥΣ ΠΡΟΜΗΘΕΥΤΕΣ» Ρωτάμε: «Υπάρχει συγκεκριμένη περίοδος μέσα στο έτος που ανοίγει η αξιολόγηση νέων συνεργατών;» Μπορεί να γίνει future lead."
      ]
