        "100. Μετά την ολοκλήρωση Ο πωλητής επιστρέφει. «Μείνατε ικανοποιημένοι;» Μετά: «Υπάρχει κάποιο άλλο project όπου μπορούμε να βοηθήσουμε;» Και ο κύκλος ξαναρχίζει.",
